(window.JUR_IMPORT = window.JUR_IMPORT || []).push([{"tribunal": "STF", "n": "1", "texto": "É vedada a expulsão de estrangeiro casado com Brasileira, ou que tenha filho Brasileiro, dependente da economia paterna.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 33.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula1/false"}, {"tribunal": "STF", "n": "2", "texto": "Concede-se liberdade vigiada ao extraditando que estiver preso por prazo superior a sessenta dias.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 33.", "situacao": "Vigente", "obs": "Veja HC 47663 (DJ de 27/11/1970).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula2/false"}, {"tribunal": "STF", "n": "3", "texto": "A imunidade concedida a deputados estaduais é restrita à Justiça do Estado. (Superada)", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 33.", "situacao": "Superada", "obs": "A Súmula 3 foi declarada superada no julgamento do RE 456679 (DJ de 07/04/2006).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula3/false"}, {"tribunal": "STF", "n": "4", "texto": "Não perde a imunidade parlamentar o congressista nomeado Ministro de Estado. (Cancelada)", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 34.", "situacao": "Cancelada", "obs": "A Súmula 4 foi cancelada no julgamento do Inq 104 (DJ de 02/10/1981).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula4/false"}, {"tribunal": "STF", "n": "5", "texto": "A sanção do projeto supre a falta de iniciativa do Poder Executivo.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 34.", "situacao": "Vigente", "obs": "Veja ADI 1381 MC (DJ de 06/06/2003) e Rp 890 (DJ de 07/06/1974).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula5/false"}, {"tribunal": "STF", "n": "6", "texto": "A revogação ou anulação, pelo Poder Executivo, de aposentadoria, ou qualquer outro ato aprovado pelo Tribunal de Contas, não produz efeitos antes de aprovada por aquele Tribunal, ressalvada a competência revisora do Judiciário.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 34.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula6/false"}, {"tribunal": "STF", "n": "7", "texto": "Sem prejuízo de recurso para o Congresso, não é exeqüível contrato administrativo a que o Tribunal de Contas houver negado registro.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 35.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula7/false"}, {"tribunal": "STF", "n": "8", "texto": "Diretor de sociedade de economia mista pode ser destituído no curso do mandato.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 35.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula8/false"}, {"tribunal": "STF", "n": "9", "texto": "Para o acesso de auditores ao Superior Tribunal Militar, só concorrem os de segunda entrância.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 35.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula9/false"}, {"tribunal": "STF", "n": "10", "texto": "O tempo de serviço militar conta-se para efeito de disponibilidade e aposentadoria do servidor público estadual.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 36.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula10/false"}, {"tribunal": "STF", "n": "11", "texto": "A vitaliciedade não impede a extinção do cargo, ficando o funcionário em disponibilidade, com todos os vencimentos.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 36.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula11/false"}, {"tribunal": "STF", "n": "12", "texto": "A vitaliciedade do professor catedrático não impede o desdobramento da cátedra.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 36.", "situacao": "Vigente", "obs": "Veja Súmula 46.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula12/false"}, {"tribunal": "STF", "n": "13", "texto": "A equiparação de extranumerário a funcionário efetivo, determinada pela L. 2.284, de 9.8.54, não envolve reestruturação, não compreendendo, portanto, os vencimentos.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 37.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula13/false"}, {"tribunal": "STF", "n": "14", "texto": "Não é admissível, por ato administrativo, restringir, em razão da idade, inscrição em concurso para cargo público.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 37.", "situacao": "Vigente", "obs": "- Veja Súmula 683. - Veja RE 74355 (DJ de 13/09/1974).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula14/false"}, {"tribunal": "STF", "n": "15", "texto": "Dentro do prazo de validade do concurso, o candidato aprovado tem o direito à nomeação, quando o cargo for preenchido sem observância da classificação.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 37.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula15/false"}, {"tribunal": "STF", "n": "16", "texto": "Funcionário nomeado por concurso tem direito à posse.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 38.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula16/false"}, {"tribunal": "STF", "n": "17", "texto": "A nomeação de funcionário sem concurso pode ser desfeita antes da posse.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 38.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula17/false"}, {"tribunal": "STF", "n": "18", "texto": "Pela falta residual, não compreendida na absolvição pelo juízo criminal, é admissível a punição administrativa do servidor público.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 38.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula18/false"}, {"tribunal": "STF", "n": "19", "texto": "É inadmissível segunda punição de servidor público, baseada no mesmo processo em que se fundou a primeira.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 39.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula19/false"}, {"tribunal": "STF", "n": "20", "texto": "É necessário processo administrativo com ampla defesa, para demissão de funcionário admitido por concurso.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 39.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula20/false"}, {"tribunal": "STF", "n": "21", "texto": "Funcionário em estágio probatório não pode ser exonerado nem demitido sem inquérito ou sem as formalidades legais de apuração de sua capacidade.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 39.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula21/false"}, {"tribunal": "STF", "n": "22", "texto": "O estágio probatório não protege o funcionário contra a extinção do cargo.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 40.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula22/false"}, {"tribunal": "STF", "n": "23", "texto": "Verificados os pressupostos legais para o licenciamento da obra, não o impede a declaração de utilidade pública para desapropriação do imóvel, mas o valor da obra não se incluirá na indenização, quando a desapropriação fôr efetivada.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 40.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula23/false"}, {"tribunal": "STF", "n": "24", "texto": "Funcionário interino substituto é livremente demissível, mesmo antes de cessar a causa da substituição.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 41. Republicação: DJ de 08/05/1964, p. 1241; DJ de 11/05/1964, p. 1257; DJ de 12/05/1964, p. 1281.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula24/false"}, {"tribunal": "STF", "n": "25", "texto": "A nomeação a termo não impede a livre demissão pelo Presidente da República, de ocupante de cargo dirigente de autarquia.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 41.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula25/false"}, {"tribunal": "STF", "n": "26", "texto": "Os servidores do Instituto de Aposentadoria e Pensões dos Industriários não podem acumular a sua gratificação bienal com o adicional de tempo de serviço previsto no Estatuto dos Funcionários Civis da União.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 41.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula26/false"}, {"tribunal": "STF", "n": "27", "texto": "Os servidores públicos não têm vencimentos irredutíveis, prerrogativa dos membros do Poder Judiciário e dos que lhes são equiparados.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 42.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula27/false"}, {"tribunal": "STF", "n": "28", "texto": "O estabelecimento bancário é responsável pelo pagamento de cheque falso, ressalvadas as hipóteses de culpa exclusiva ou concorrente do correntista.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 42.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula28/false"}, {"tribunal": "STF", "n": "29", "texto": "Gratificação devida a servidores do \"sistema fazendário\" não se estende aos dos Tribunais de Contas.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 42.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula29/false"}, {"tribunal": "STF", "n": "30", "texto": "Servidores de coletorias não têm direito à percentagem pela cobrança de contribuições destinadas à Petrobrás.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 43.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula30/false"}, {"tribunal": "STF", "n": "31", "texto": "Para aplicação da L. 1741, de 22.11.52, soma-se o tempo de serviço ininterrupto em mais de um cargo em comissão.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 43.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula31/false"}, {"tribunal": "STF", "n": "32", "texto": "Para aplicação da L. 1741, de 22.11.52, soma-se o tempo de serviço ininterrupto em cargo em comissão e em função gratificada.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 44.", "situacao": "Vigente", "obs": "Embora na publicação da Súmula 32 conste como precedente o MS 8489, trata-se do RMS 8489 (DJ de 17/05/1962).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula32/false"}, {"tribunal": "STF", "n": "33", "texto": "A L. 1.741, de 22.11.52, é aplicável às autarquias federais.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 44.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula33/false"}, {"tribunal": "STF", "n": "34", "texto": "No Estado de São Paulo, funcionário eleito vereador fica licenciado por toda a duração do mandato.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 44.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula34/false"}, {"tribunal": "STF", "n": "35", "texto": "Em caso de acidente do trabalho ou de transporte, a concubina tem direito de ser indenizada pela morte do amásio, se entre eles não havia impedimento para o matrimônio.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 45.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula35/false"}, {"tribunal": "STF", "n": "36", "texto": "Servidor vitalício está sujeito à aposentadoria compulsória, em razão da idade.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 45.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula36/false"}, {"tribunal": "STF", "n": "37", "texto": "Não tem direito de se aposentar pelo Tesouro Nacional o servidor que não satisfizer as condições estabelecidas na legislação do serviço público federal, ainda que aposentado pela respectiva instituição previdenciária, com direito, em tese, a duas aposentadorias.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 45.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula37/false"}, {"tribunal": "STF", "n": "38", "texto": "Reclassificação posterior à aposentadoria não aproveita ao servidor aposentado.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 46.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula38/false"}, {"tribunal": "STF", "n": "39", "texto": "À falta de lei, funcionário em disponibilidade não pode exigir, judicialmente, o seu aproveitamento, que fica subordinado ao critério de conveniência da administração.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 46.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula39/false"}, {"tribunal": "STF", "n": "40", "texto": "A elevação da entrância da comarca não promove automaticamente o juiz, mas não interrompe o exercício de suas funções na mesma comarca.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 46.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula40/false"}, {"tribunal": "STF", "n": "41", "texto": "Juízes preparadores ou substitutos não têm direito aos vencimentos da atividade fora dos períodos de exercício.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 47.", "situacao": "Vigente", "obs": "Veja Súmula 45.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula41/false"}, {"tribunal": "STF", "n": "42", "texto": "É legítima a equiparação de juízes do Tribunal de Contas, em direitos e garantias, aos membros do Poder Judiciário.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 47.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula42/false"}, {"tribunal": "STF", "n": "43", "texto": "Não contraria a Constituição Federal o art. 61 da Constituição de São Paulo, que equiparou os vencimentos do Ministério Público aos da magistratura.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 47.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula43/false"}, {"tribunal": "STF", "n": "44", "texto": "O exercício do cargo pelo prazo determinado na L. 1.341, de 30.1.51, art. 91, dá preferência para a nomeação interina de Procurador da República.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 47.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula44/false"}, {"tribunal": "STF", "n": "45", "texto": "A estabilidade dos substitutos do Ministério Público Militar não confere direito aos vencimentos da atividade fora dos períodos de exercício.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 48.", "situacao": "Vigente", "obs": "Veja Súmula 41.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula45/false"}, {"tribunal": "STF", "n": "46", "texto": "Desmembramento de serventia de justiça não viola o princípio de vitaliciedade do serventuário.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 48.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula46/false"}, {"tribunal": "STF", "n": "47", "texto": "Reitor de universidade não é livremente demissível pelo Presidente da República durante o prazo de sua investidura.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 48.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula47/false"}, {"tribunal": "STF", "n": "48", "texto": "É legítimo o rodízio de docentes livres na substituição do professor catedrático.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 49.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula48/false"}, {"tribunal": "STF", "n": "49", "texto": "A cláusula de inalienabilidade inclui a incomunicabilidade dos bens.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 49.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula49/false"}, {"tribunal": "STF", "n": "50", "texto": "A lei pode estabelecer condições para a demissão de extranumerário.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 49.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula50/false"}, {"tribunal": "STF", "n": "51", "texto": "Militar não tem direito a mais de duas promoções na passagem para a inatividade, ainda que por motivos diversos.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 50.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula51/false"}, {"tribunal": "STF", "n": "52", "texto": "A promoção de militar, vinculada à inatividade, pode ser feita, quando couber, a pôsto inexistente no quadro.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 50.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula52/false"}, {"tribunal": "STF", "n": "53", "texto": "A promoção de professor militar, vinculada à sua reforma, pode ser feita, quando couber, a pôsto inexistente no quadro.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 51.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula53/false"}, {"tribunal": "STF", "n": "54", "texto": "A reserva ativa do magistério militar não confere vantagens vinculadas à efetiva passagem para a inatividade.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 51.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula54/false"}, {"tribunal": "STF", "n": "55", "texto": "Militar da reserva está sujeito à pena disciplinar.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 51.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula55/false"}, {"tribunal": "STF", "n": "56", "texto": "Militar reformado não está sujeito à pena disciplinar.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 52.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula56/false"}, {"tribunal": "STF", "n": "57", "texto": "Militar inativo não tem direito ao uso do uniforme fora dos casos previstos em lei ou regulamento.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 52.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula57/false"}, {"tribunal": "STF", "n": "58", "texto": "É válida a exigência de média superior a quatro para aprovação em estabelecimento de ensino superior, consoante o respectivo regimento.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 52.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula58/false"}, {"tribunal": "STF", "n": "59", "texto": "Imigrante pode trazer, sem licença prévia, automóvel que lhe pertença desde mais de seis meses antes do seu embarque para o Brasil.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 52.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula59/false"}, {"tribunal": "STF", "n": "60", "texto": "Não pode o estrangeiro trazer automóvel quando não comprovada a transferência definitiva de sua residência para o Brasil.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 53.", "situacao": "Vigente", "obs": "Veja Súmula 59.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula60/false"}, {"tribunal": "STF", "n": "61", "texto": "Brasileiro domiciliado no estrangeiro, que se transfere definitivamente para o Brasil, pode trazer automóvel licenciado em seu nome há mais de seis meses", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 53.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula61/false"}, {"tribunal": "STF", "n": "62", "texto": "Não basta a simples estada no estrangeiro por mais de seis meses, para dar direito à trazida de automóvel com fundamento em transferência de residência.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 53.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula62/false"}, {"tribunal": "STF", "n": "63", "texto": "É indispensável, para trazida de automóvel, a prova do licenciamento há mais de seis meses no país de origem.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 54.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula63/false"}, {"tribunal": "STF", "n": "64", "texto": "É permitido trazer do estrangeiro, como bagagem, objetos de uso pessoal e doméstico, desde que, por sua quantidade e natureza, não induzam finalidade comercial.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 54.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula64/false"}, {"tribunal": "STF", "n": "65", "texto": "A cláusula de aluguel progressivo anterior à L. 3.494, de 19.12.58, continua em vigor em caso de prorrogação legal ou convencional da locação.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 54.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula65/false"}, {"tribunal": "STF", "n": "66", "texto": "É legítima a cobrança do tributo que houver sido aumentado após o orçamento, mas antes do início do respectivo exercício financeiro.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 55.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula66/false"}, {"tribunal": "STF", "n": "67", "texto": "É inconstitucional a cobrança do tributo que houver sido criado ou aumentado no mesmo exercício financeiro.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 55.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula67/false"}, {"tribunal": "STF", "n": "68", "texto": "É legítima a cobrança, pelos Municípios, no exercício de 1961, de tributo estadual, regularmente criado ou aumentado, e que lhes foi transferido pela Emenda Constitucional nº 5, de 21.11.61.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 56.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula68/false"}, {"tribunal": "STF", "n": "69", "texto": "A Constituição estadual não pode estabelecer limite para o aumento de tributos municipais.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 56. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula69/false"}, {"tribunal": "STF", "n": "70", "texto": "É inadmissível a interdição de estabelecimento como meio coercitivo para cobrança de tributo.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 56.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula70/false"}, {"tribunal": "STF", "n": "71", "texto": "Embora pago indevidamente, não cabe restituição de tributo indireto.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 57.", "situacao": "Vigente", "obs": "Veja Súmula 546.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula71/false"}, {"tribunal": "STF", "n": "72", "texto": "No julgamento de questão constitucional, vinculada a decisão do Tribunal Superior Eleitoral, não estão impedidos os Ministros do Supremo Tribunal Federal que ali tenham funcionado no mesmo processo, ou no processo originário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 57.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula72/false"}, {"tribunal": "STF", "n": "73", "texto": "A imunidade das autarquias, implicitamente contida no art. 31, V, \"a\", da Constituição Federal, abrange tributos estaduais e municipais.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 57.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula73/false"}, {"tribunal": "STF", "n": "74", "texto": "O imóvel transcrito em nome de autarquia, embora objeto de promessa de venda a particulares, continua imune de impostos locais.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 58.", "situacao": "Vigente", "obs": "- Veja Súmula 73 e Súmula 583. - Veja RE 69781 (DJ de 05/03/1971).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula74/false"}, {"tribunal": "STF", "n": "75", "texto": "Sendo vendedora uma autarquia, a sua imunidade fiscal não compreende o impôsto de transmissão \"inter vivos\", que é encargo do comprador.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 58.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula75/false"}, {"tribunal": "STF", "n": "76", "texto": "As sociedades de economia mista não estão protegidas pela imunidade fiscal do art. 31, V, \"a\", Constituição Federal.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 58. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula76/false"}, {"tribunal": "STF", "n": "77", "texto": "Está isenta de impostos federais a aquisição de bens pela Rêde Ferroviária Federal.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 59.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula77/false"}, {"tribunal": "STF", "n": "78", "texto": "Estão isentas de impostos locais as emprêsas de energia elétrica, no que respeita às suas atividades específicas.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 59.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula78/false"}, {"tribunal": "STF", "n": "79", "texto": "O Banco do Brasil não tem isenção de tributos locais.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 59. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula79/false"}, {"tribunal": "STF", "n": "80", "texto": "Para a retomada de prédio situado fora do domicílio do locador exige-se a prova da necessidade.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 59.", "situacao": "Vigente", "obs": "Veja Súmula 483.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula80/false"}, {"tribunal": "STF", "n": "81", "texto": "As cooperativas não gozam de isenção de impostos locais, com fundamento na Constituição e nas leis federais.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 60.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula81/false"}, {"tribunal": "STF", "n": "82", "texto": "São inconstitucionais o impôsto de cessão e a taxa sôbre inscrição de promessa de venda de imóvel, substitutivos do impôsto de transmissão, por incidirem sôbre ato que não transfere o domínio.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 60.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula82/false"}, {"tribunal": "STF", "n": "83", "texto": "Os ágios de importação incluem-se no valor dos artigos importados para incidência do impôsto de consumo.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 61.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula83/false"}, {"tribunal": "STF", "n": "84", "texto": "Não estão isentos do impôsto de consumo os produtos importados pelas cooperativas.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 61.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula84/false"}, {"tribunal": "STF", "n": "85", "texto": "Não estão sujeitos ao impôsto de consumo os bens de uso pessoal e doméstico trazidos, como bagagem, do exterior.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 61.", "situacao": "Vigente", "obs": "Veja Súmula 86.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula85/false"}, {"tribunal": "STF", "n": "86", "texto": "Não está sujeito ao impôsto de consumo automóvel usado, trazido do exterior pelo proprietário.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 61.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula86/false"}, {"tribunal": "STF", "n": "87", "texto": "Somente no que não colidirem com a L. 3.244, de 14.8.57, são aplicáveis acordos tarifários anteriores.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 62.", "situacao": "Vigente", "obs": "Veja Súmula 88.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula87/false"}, {"tribunal": "STF", "n": "88", "texto": "É válida a majoração da tarifa alfandegária, resultante da L. 3.244, de 14.8.57, que modificou o Acordo Geral sôbre Tarifas Aduaneiras e Comércio (GATT), aprovado pela L. 313, de 30.7.48.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 62.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula88/false"}, {"tribunal": "STF", "n": "89", "texto": "Estão isentas do impôsto de importação frutas importadas da Argentina, do Chile, da Espanha e de Portugal, enquanto vigentes os respectivos acordos comerciais.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 62.", "situacao": "Vigente", "obs": "Embora na publicação da Súmula 89 conste como precedente o RMS 9147, trata-se do MS 9147 AgR (DJ de 25/01/1962).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula89/false"}, {"tribunal": "STF", "n": "90", "texto": "É legítima a lei local que faça incidir o impôsto de indústrias e profissões com base no movimento econômico do contribuinte.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 63.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula90/false"}, {"tribunal": "STF", "n": "91", "texto": "A incidência do impôsto único não isenta o comerciante de combustíveis do impôsto de indústrias e profissões.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 63.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula91/false"}, {"tribunal": "STF", "n": "92", "texto": "É constitucional o art. 100, nº II, da L. 4.563, de 20.2.57, do Município de Recife, que faz variar o impôsto de licença em função do aumento do capital do contribuinte.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 64.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula92/false"}, {"tribunal": "STF", "n": "93", "texto": "Não está isenta do impôsto de renda a atividade profissional do arquiteto.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 64.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula93/false"}, {"tribunal": "STF", "n": "94", "texto": "É competente a autoridade alfandegária para o desconto, na fonte, do impôsto de renda correspondente às comissões dos despachantes aduaneiros.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 64.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula94/false"}, {"tribunal": "STF", "n": "95", "texto": "Para cálculo do impôsto de lucro extraordinário, incluem-se no capital as reservas do ano-base, apuradas em balanço.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 64.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula95/false"}, {"tribunal": "STF", "n": "96", "texto": "O impôsto de lucro imobiliário incide sôbre a venda de imóvel da meação do cônjuge sobrevivente, ainda que aberta a sucessão antes da vigência da L. 3.470, de 28.11.58.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 65.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula96/false"}, {"tribunal": "STF", "n": "97", "texto": "É devida a alíquota anterior do impôsto de lucro imobiliário, quando a promessa de venda houver sido celebrada antes da vigência da lei que a tiver elevado.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 65.", "situacao": "Vigente", "obs": "Veja Súmula 112.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula97/false"}, {"tribunal": "STF", "n": "98", "texto": "Sendo o imóvel alienado na vigência da L. 3.470, de 28.11.58, ainda que adquirido por herança, usucapião ou a título gratuito, é devido o impôsto de lucro imobiliário.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 66.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula98/false"}, {"tribunal": "STF", "n": "99", "texto": "Não é devido o impôsto de lucro imobiliário, quando a alienação de imóvel adquirido por herança, ou a título gratuito, tiver sido anterior à vigência da L. 3.470, de 28.11.58.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 66.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula99/false"}, {"tribunal": "STF", "n": "100", "texto": "Não é devido o impôsto de lucro imobiliário, quando a alienação de imóvel, adquirido por usucapião, tiver sido anterior à vigência da L. 3.470, de 28.11.58.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 66.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula100/false"}, {"tribunal": "STF", "n": "101", "texto": "O mandado de segurança não substitui a ação popular.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 67.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula101/false"}, {"tribunal": "STF", "n": "102", "texto": "É devido o impôsto federal do selo pela incorporação de reservas, em reavaliação de ativo, ainda que realizada antes da vigência da L. 3.519, de 30.12.58.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 67.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula102/false"}, {"tribunal": "STF", "n": "103", "texto": "É devido o impôsto federal do selo na simples reavaliação de ativo, realizada posteriormente à vigência da L. 3.519, de 30.12.58.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 67.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula103/false"}, {"tribunal": "STF", "n": "104", "texto": "Não é devido o impôsto federal do selo na simples reavaliação de ativo anterior à vigência da L. 3.519, de 30.12.58.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 68.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula104/false"}, {"tribunal": "STF", "n": "105", "texto": "Salvo se tiver havido premeditação, o suicídio do segurado no período contratual de carência não exime o segurador do pagamento do seguro.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 68.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula105/false"}, {"tribunal": "STF", "n": "106", "texto": "É legítima a cobrança de sêlo sôbre registro de automóveis, na conformidade da legislação estadual.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 68. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula106/false"}, {"tribunal": "STF", "n": "107", "texto": "É inconstitucional o impôsto de selo de 3%, \"ad valorem\", do Paraná, quanto aos produtos remetidos para fora do Estado.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 69.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula107/false"}, {"tribunal": "STF", "n": "108", "texto": "É legítima a incidência do impôsto de transmissão \"inter vivos\" sôbre o valor do imóvel ao tempo da alienação e não da promessa, na conformidade da legislação local.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 69.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula108/false"}, {"tribunal": "STF", "n": "109", "texto": "É devida a multa prevista no art. 15, § 6º, da L. 1.300, de 28.12.50, ainda que a desocupação do imóvel tenha resultado da notificação e não haja sido proposta ação de despejo.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 69.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula109/false"}, {"tribunal": "STF", "n": "110", "texto": "O impôsto de transmissão \"inter vivos\" não incide sôbre a construção, ou parte dela, realizada pelo adquirente, mas sôbre o que tiver sido construído ao tempo da alienação do terreno.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 70.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula110/false"}, {"tribunal": "STF", "n": "111", "texto": "É legítima a incidência do impôsto de transmissão \"inter vivos\" sôbre a restituição, ao antigo proprietário, de imóvel que deixou de servir à finalidade da sua desapropriação.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 70.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula111/false"}, {"tribunal": "STF", "n": "112", "texto": "O impôsto de transmissão \"causa mortis\" é devido pela alíquota vigente ao tempo da abertura da sucessão.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 70.", "situacao": "Vigente", "obs": "Veja Súmula 97.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula112/false"}, {"tribunal": "STF", "n": "113", "texto": "O impôsto de transmissão \"causa mortis\" é calculado sôbre o valor dos bens na data da avaliação.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 71.", "situacao": "Vigente", "obs": "Veja Súmula 590.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula113/false"}, {"tribunal": "STF", "n": "114", "texto": "O impôsto de transmissão \"causa mortis\" não é exigível antes da homologação do cálculo.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 71.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula114/false"}, {"tribunal": "STF", "n": "115", "texto": "Sôbre os honorários do advogado contratado pelo inventariante, com a homologação do juiz, não incide o impôsto de transmissão \"causa mortis\".", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 71.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula115/false"}, {"tribunal": "STF", "n": "116", "texto": "Em desquite ou inventário, é legítima a cobrança do chamado impôsto de reposição, quando houver desigualdade nos valôres partilhados.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 72.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula116/false"}, {"tribunal": "STF", "n": "117", "texto": "A lei estadual pode fazer variar a alíquota do impôsto de vendas e consignações em razão da espécie do produto.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 72.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula117/false"}, {"tribunal": "STF", "n": "118", "texto": "Estão sujeitas ao impôsto de vendas e consignações as transações sôbre minerais, que ainda não estão compreendidos na legislação federal sôbre o impôsto único.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p.72.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula118/false"}, {"tribunal": "STF", "n": "119", "texto": "É devido o impôsto de vendas e consignações sôbre a venda de cafés ao Instituto Brasileiro do Café, embora o lote, originariamente, se destinasse à exportação.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 72.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula119/false"}, {"tribunal": "STF", "n": "120", "texto": "Parede de tijolos de vidro translúcido pode ser levantada a menos de metro e meio do prédio vizinho, não importando servidão sôbre êle.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 73.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula120/false"}, {"tribunal": "STF", "n": "121", "texto": "É vedada a capitalização de juros, ainda que expressamente convencionada.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 73.", "situacao": "Vigente", "obs": "Veja Súmula 596.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula121/false"}, {"tribunal": "STF", "n": "122", "texto": "O enfiteuta pode purgar a mora enquanto não decretado o comisso por sentença.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 74.", "situacao": "Vigente", "obs": "Veja Súmula 169.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula122/false"}, {"tribunal": "STF", "n": "123", "texto": "Sendo a locação regida pelo D. 24.150, de 20.4.34, o locatário não tem direito à purgação da mora prevista na L. 1.300, de 28.12.50.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 74.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula123/false"}, {"tribunal": "STF", "n": "124", "texto": "É inconstitucional o adicional do impôsto de vendas e consignações cobrado pelo Estado do Espírito Santo sôbre cafés da cota de expurgo entregues ao Instituto Brasileiro do Café.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 74.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula124/false"}, {"tribunal": "STF", "n": "125", "texto": "Não é devido o impôsto de vendas e consignações sôbre a parcela do impôsto de consumo que onera a primeira venda realizada pelo produtor.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 75.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula125/false"}, {"tribunal": "STF", "n": "126", "texto": "É inconstitucional a chamada taxa de aguardente, do Instituto do Açúcar e do Álcool.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 75.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula126/false"}, {"tribunal": "STF", "n": "127", "texto": "É indevida a taxa de armazenagem, posteriormente aos primeiros trinta dias, quando não exigível o impôsto de consumo, cuja cobrança tenha motivado a retenção da mercadoria.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 76.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula127/false"}, {"tribunal": "STF", "n": "128", "texto": "É indevida a taxa de assistência médica e hospitalar das instituições de previdência social.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 76.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula128/false"}, {"tribunal": "STF", "n": "129", "texto": "Na conformidade da legislação local, é legítima a cobrança de taxa de calçamento.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 76.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula129/false"}, {"tribunal": "STF", "n": "130", "texto": "A taxa de despacho aduaneiro (art. 66 da L. 3.244, de 14.8.57) continua a ser exigível após o Dec. Legisl. 14, de 25.8.60, que aprovou alterações introduzidas no Acordo Geral sôbre Tarifas Aduaneiras e Comércio (GATT).", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 77.", "situacao": "Vigente", "obs": "- Veja Súmula 131 e Súmula 308. - Veja RE 69234 (DJ de 05/03/1971).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula130/false"}, {"tribunal": "STF", "n": "131", "texto": "A taxa de despacho aduaneiro (art. 66 da L. 3.244, de 14.8.57) continua a ser exigível após o Dec. Legisl. 14, de 25.8.60, mesmo para as mercadorias incluídas na vigente lista III do Acordo Geral sôbre Tarifas Aduaneiras e Comércio (GATT).", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 77.", "situacao": "Vigente", "obs": "- Veja Súmula 130 e Súmula 308. - Veja RE 69234 (DJ de 05/03/1971). - Embora na publicação da Súmula 131 conste como precedente o RMS 8558, trata-se do MS 8558 AgR (DJ de 19/10/1961). - Embora na publicação da Súmula 131 conste como precedente o RMS 8827, trata-se do MS 8827 AgR (DJ de 09/11/1961). - Embora na publicação da Súmula 131 conste como precedente o RMS 8829, trata-se do MS 8829 AgR (DJ de 14/12/1961). - Embora na publicação da Súmula 131 conste como precedente o RMS 8830, trata-se do MS 8830 AgR (DJ de 01/06/1962).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula131/false"}, {"tribunal": "STF", "n": "132", "texto": "Não é devida a taxa de previdência social na importação de amianto bruto ou em fibra.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 77.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula132/false"}, {"tribunal": "STF", "n": "133", "texto": "Não é devida a taxa de despacho aduaneiro na importação de fertilizantes e inseticidas.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 78. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula133/false"}, {"tribunal": "STF", "n": "134", "texto": "A isenção fiscal para a importação de frutas da Argentina compreende a taxa de despacho aduaneiro e a taxa de previdência social.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 78.", "situacao": "Vigente", "obs": "Embora na publicação da Súmula 134 conste como precedente o RMS 9147, trata-se do MS 9147 AgR (DJ de 25/01/1962).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula134/false"}, {"tribunal": "STF", "n": "135", "texto": "É inconstitucional a taxa de eletrificação de Pernambuco.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 79. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula135/false"}, {"tribunal": "STF", "n": "136", "texto": "É constitucional a taxa de estatística da Bahia.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 79. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula136/false"}, {"tribunal": "STF", "n": "137", "texto": "A taxa de fiscalização da exportação incide sôbre a bonificação cambial concedida ao exportador.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 79.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula137/false"}, {"tribunal": "STF", "n": "138", "texto": "É inconstitucional a taxa contra fogo, do estado de Minas Gerais, incidente sôbre prêmio de seguro contra fogo.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 80. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula138/false"}, {"tribunal": "STF", "n": "139", "texto": "É indevida a cobrança do impôsto de transação a que se refere a L. 899, de 1957, art. 58, IV, letra \"e\", do antigo Distrito Federal.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 80.", "situacao": "Vigente", "obs": "Veja Súmula 82.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula139/false"}, {"tribunal": "STF", "n": "140", "texto": "Na importação de lubrificantes é devida a taxa de previdência social.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 80.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula140/false"}, {"tribunal": "STF", "n": "141", "texto": "Não incide a taxa de previdência social sôbre combustíveis.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 81.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula141/false"}, {"tribunal": "STF", "n": "142", "texto": "Não é devida a taxa de previdência social sôbre mercadorias isentas do impôsto de importação.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 81.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula142/false"}, {"tribunal": "STF", "n": "143", "texto": "Na forma da lei estadual, é devido o impôsto de vendas e consignações na exportação de café pelo Estado da Guanabara, embora proveniente de outro Estado.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 81.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula143/false"}, {"tribunal": "STF", "n": "144", "texto": "É inconstitucional a incidência da taxa de recuperação econômica de Minas Gerais sôbre contrato sujeito ao impôsto federal do sêlo.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 82. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula144/false"}, {"tribunal": "STF", "n": "145", "texto": "Não há crime, quando a preparação do flagrante pela polícia torna impossível a sua consumação.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 82.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula145/false"}, {"tribunal": "STF", "n": "146", "texto": "A prescrição da ação penal regula-se pela pena concretizada na sentença, quando não há recurso da acusação.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 82.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula146/false"}, {"tribunal": "STF", "n": "147", "texto": "A prescrição de crime falimentar começa a correr da data em que deveria estar encerrada a falência, ou do trânsito em julgado da sentença que a encerrar ou que julgar cumprida a concordata.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 83.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula147/false"}, {"tribunal": "STF", "n": "148", "texto": "É legítimo o aumento de tarifas portuárias por ato do Ministro da Viação e Obras Públicas.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 83. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula148/false"}, {"tribunal": "STF", "n": "149", "texto": "É imprescritível a ação de investigação de paternidade, mas não o é a de petição de herança.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 83.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula149/false"}, {"tribunal": "STF", "n": "150", "texto": "Prescreve a execução no mesmo prazo de prescrição da ação.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 84.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula150/false"}, {"tribunal": "STF", "n": "151", "texto": "Prescreve em um ano a ação do segurador subrogado para haver indenização por extravio ou perda de carga transportada por navio.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 84.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula151/false"}, {"tribunal": "STF", "n": "152", "texto": "A ação para anular venda de ascendente a descendente, sem consentimento dos demais, prescreve em quatro anos a contar da abertura da sucessão. (Revogada)", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 84.", "situacao": "Cancelada", "obs": "A Súmula 152 foi revogada pela Súmula 494.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula152/false"}, {"tribunal": "STF", "n": "153", "texto": "Simples protesto cambiário não interrompe a prescrição.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 85.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula153/false"}, {"tribunal": "STF", "n": "154", "texto": "Simples vistoria não interrompe a prescrição.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 85.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula154/false"}, {"tribunal": "STF", "n": "155", "texto": "É relativa a nulidade do processo criminal por falta de intimação da expedição de precatória para inquirição de testemunha.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 85.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula155/false"}, {"tribunal": "STF", "n": "156", "texto": "É absoluta a nulidade do julgamento, pelo júri, por falta de quesito obrigatório.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 85.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula156/false"}, {"tribunal": "STF", "n": "157", "texto": "É necessária prévia autorização do Presidente da República para desapropriação, pelos Estados, de emprêsa de energia elétrica.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 86.", "situacao": "Vigente", "obs": "Veja RE 75482 (DJ de 10/09/1973).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula157/false"}, {"tribunal": "STF", "n": "158", "texto": "Salvo estipulação contratual averbada no registro imobiliário, não responde o adquirente pelas benfeitorias do locatário.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 86.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula158/false"}, {"tribunal": "STF", "n": "159", "texto": "Cobrança excessiva, mas de boa-fé, não dá lugar às sanções do art. 1.531 do Código Civil.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 86.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula159/false"}, {"tribunal": "STF", "n": "160", "texto": "É nula a decisão do Tribunal que acolhe, contra o réu, nulidade não argüida no recurso da acusação, ressalvados os casos de recurso de ofício.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 87.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula160/false"}, {"tribunal": "STF", "n": "161", "texto": "Em contrato de transporte, é inoperante a cláusula de não indenizar.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 87.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula161/false"}, {"tribunal": "STF", "n": "162", "texto": "É absoluta a nulidade do julgamento pelo júri, quando os quesitos da defesa não precedem aos das circunstâncias agravantes.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 88.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula162/false"}, {"tribunal": "STF", "n": "163", "texto": "Salvo contra a Fazenda Pública, sendo a obrigação ilíquida, contam-se os juros moratórios desde a citação inicial para a ação.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p.88.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula163/false"}, {"tribunal": "STF", "n": "164", "texto": "No processo de desapropriação, são devidos juros compensatórios desde a antecipada imissão de posse, ordenada pelo juiz, por motivo de urgência.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 88.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula164/false"}, {"tribunal": "STF", "n": "165", "texto": "A venda realizada diretamente pelo mandante ao mandatário não é atingida pela nulidade do art. 1.133, II, do Código Civil.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 89.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula165/false"}, {"tribunal": "STF", "n": "166", "texto": "É inadmissível o arrependimento no compromisso de compra e venda sujeito ao regime do Dl. 58, de 10.12.37.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 89.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula166/false"}, {"tribunal": "STF", "n": "167", "texto": "Não se aplica o regime do Dl. 58, de 10.12.37, ao compromisso de compra e venda não inscrito no registro imobiliário, salvo se o promitente vendedor se obrigou a efetuar o registro.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 89.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula167/false"}, {"tribunal": "STF", "n": "168", "texto": "Para os efeitos do Dl. 58, de 10.12.37, admite-se a inscrição imobiliária do compromisso de compra e venda no curso da ação.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 90.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula168/false"}, {"tribunal": "STF", "n": "169", "texto": "Depende de sentença a aplicação da pena de comisso.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 90.", "situacao": "Vigente", "obs": "Veja Súmula 122.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula169/false"}, {"tribunal": "STF", "n": "170", "texto": "É resgatável a enfiteuse instituída anteriormente à vigência do Código Civil.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 90.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula170/false"}, {"tribunal": "STF", "n": "171", "texto": "Não se admite, na locação em curso, de prazo determinado, a majoração de encargos a que se refere a L. 3.844, de 15.12.60.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 91.", "situacao": "Vigente", "obs": "Veja Súmula 172.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula171/false"}, {"tribunal": "STF", "n": "172", "texto": "Não se admite, na locação em curso, de prazo determinado, o reajustamento de aluguel a que se refere a L. 3.085, de 29.12.56.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 91.", "situacao": "Vigente", "obs": "Veja Súmula 171.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula172/false"}, {"tribunal": "STF", "n": "173", "texto": "Em caso de obstáculo judicial admite-se a purga da mora, pelo locatário, além do prazo legal.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 91.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula173/false"}, {"tribunal": "STF", "n": "174", "texto": "Para a retomada do imóvel alugado, não é necessária a comprovação dos requisitos legais na notificação prévia.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 91.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula174/false"}, {"tribunal": "STF", "n": "175", "texto": "Admite-se a retomada de imóvel alugado para uso de filho que vai contrair matrimônio.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 92.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula175/false"}, {"tribunal": "STF", "n": "176", "texto": "O promitente comprador, nas condições previstas na L. 1.300, de 28-12-50, pode retomar o imóvel locado.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 92.", "situacao": "Vigente", "obs": "Veja Súmula 177.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula176/false"}, {"tribunal": "STF", "n": "177", "texto": "O cessionário do promitente comprador, nas mesmas condições dêste, pode retomar o imóvel locado.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 92.", "situacao": "Vigente", "obs": "Veja Súmula 176.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula177/false"}, {"tribunal": "STF", "n": "178", "texto": "Não excederá de cinco anos a renovação judicial de contrato de locação, fundada no D. 24.150, de 20.4.34.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 93.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula178/false"}, {"tribunal": "STF", "n": "179", "texto": "O aluguel arbitrado judicialmente nos têrmos da L. 3.085, de 29.12.56, art. 6º, vigora a partir da data do laudo pericial.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 93.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula179/false"}, {"tribunal": "STF", "n": "180", "texto": "Na ação revisional do art. 31 do D. 24.150, de 20.4.34, o aluguel arbitrado vigora a partir do laudo pericial.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 93.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula180/false"}, {"tribunal": "STF", "n": "181", "texto": "Na retomada, para construção mais útil de imóvel sujeito ao D. 24.150, de 20.4.34, é sempre devida indenização para despesas de mudança do locatário.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 94.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula181/false"}, {"tribunal": "STF", "n": "182", "texto": "Não impede o reajustamento do débito pecuário, nos termos da L. 1.002, de 24.12.49, a falta de cancelamento da renúncia à moratória da L. 209, de 2.1.48.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 94.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula182/false"}, {"tribunal": "STF", "n": "183", "texto": "Não se incluem no reajustamento pecuário dívidas estranhas à atividade agropecuária.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 94.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula183/false"}, {"tribunal": "STF", "n": "184", "texto": "Não se incluem no reajustamento pecuário dívidas contraídas posteriormente a 19.12.46.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 95.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula184/false"}, {"tribunal": "STF", "n": "185", "texto": "Em processo de reajustamento pecuário, não responde a União pelos honorários do advogado do credor ou do devedor.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 95.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula185/false"}, {"tribunal": "STF", "n": "186", "texto": "Não infringe a lei a tolerância da quebra de 1% no transporte por estrada de ferro, prevista no regulamento de transportes.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 96. Republicação: DJ de 08/05/1964, p. 1241; DJ de 11/05/1964, p. 1257; DJ de 12/05/1964, p. 1281", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula186/false"}, {"tribunal": "STF", "n": "187", "texto": "A responsabilidade contratual do transportador, pelo acidente com o passageiro, não é elidida por culpa de terceiro, contra o qual tem ação regressiva.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 96.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula187/false"}, {"tribunal": "STF", "n": "188", "texto": "O segurador tem ação regressiva contra o causador do dano, pelo que efetivamente pagou, até ao limite previsto no contrato de seguro.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 96.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula188/false"}, {"tribunal": "STF", "n": "189", "texto": "Avais em branco e superpostos consideram-se simultâneos e não sucessivos.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 97.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula189/false"}, {"tribunal": "STF", "n": "190", "texto": "O não pagamento de título vencido há mais de trinta dias, sem protesto, não impede a concordata preventiva.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 97.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula190/false"}, {"tribunal": "STF", "n": "191", "texto": "Inclui-se no crédito habilitado em falência a multa fiscal simplesmente moratória.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 97.", "situacao": "Vigente", "obs": "Veja Súmula 192 e Súmula 565.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula191/false"}, {"tribunal": "STF", "n": "192", "texto": "Não se inclui no crédito habilitado em falência a multa fiscal com efeito de pena administrativa.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 98.", "situacao": "Vigente", "obs": "Veja Súmula 191 e Súmula 565.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula192/false"}, {"tribunal": "STF", "n": "193", "texto": "Para a restituição prevista no art. 76, § 2º, da Lei de Falências, conta-se o prazo de quinze dias da entrega da coisa e não da sua remessa.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 98.", "situacao": "Vigente", "obs": "Veja Súmula 417 e Súmula 495.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula193/false"}, {"tribunal": "STF", "n": "194", "texto": "É competente o Ministro do Trabalho para a especificação das atividades insalubres.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 98.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula194/false"}, {"tribunal": "STF", "n": "195", "texto": "Contrato de trabalho para obra certa, ou de prazo determinado, transforma-se em contrato de prazo indeterminado, quando prorrogado por mais de quatro anos.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 98.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula195/false"}, {"tribunal": "STF", "n": "196", "texto": "Ainda que exerça atividade rural, o empregado de emprêsa industrial ou comercial é classificado de acôrdo com a categoria do empregador.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 99.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula196/false"}, {"tribunal": "STF", "n": "197", "texto": "O empregado com representação sindical só pode ser despedido mediante inquérito em que se apure falta grave.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 99.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula197/false"}, {"tribunal": "STF", "n": "198", "texto": "As ausências motivadas por acidente do trabalho não são descontáveis do período aquisitivo das férias.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 99.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula198/false"}, {"tribunal": "STF", "n": "199", "texto": "O salário das férias do empregado horista corresponde à média do período aquisitivo, não podendo ser inferior ao mínimo.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 100.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula199/false"}, {"tribunal": "STF", "n": "200", "texto": "Não é inconstitucional a L. 1.530, de 26.12.51, que manda incluir na indenização por despedida injusta parcela correspondente a férias proporcionais.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 100.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula200/false"}, {"tribunal": "STF", "n": "201", "texto": "O vendedor pracista, remunerado mediante comissão, não tem direito ao repouso semanal remunerado.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 100.", "situacao": "Vigente", "obs": "Veja RE 79238 (DJ de 11/03/1977).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula201/false"}, {"tribunal": "STF", "n": "202", "texto": "Na equiparação de salário, em caso de trabalho igual, toma-se em conta o tempo de serviço na função, e não no emprêgo.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 101.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula202/false"}, {"tribunal": "STF", "n": "203", "texto": "Não está sujeita à vacância de 60 dias a vigência de novos níveis de salário mínimo.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 101.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula203/false"}, {"tribunal": "STF", "n": "204", "texto": "Tem direito o trabalhador substituto, ou de reserva, ao salário mínimo no dia em que fica à disposição do empregador sem ser aproveitado na função específica; se aproveitado, recebe o salário contratual.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 101.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula204/false"}, {"tribunal": "STF", "n": "205", "texto": "Tem direito a salário integral o menor não sujeito a aprendizagem metódica.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 102.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula205/false"}, {"tribunal": "STF", "n": "206", "texto": "É nulo o julgamento ulterior pelo júri com a participação de jurado que funcionou em julgamento anterior do mesmo processo.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 102.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula206/false"}, {"tribunal": "STF", "n": "207", "texto": "As gratificações habituais, inclusive a de Natal, consideram-se tacitamente convencionadas, integrando o salário.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 102.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula207/false"}, {"tribunal": "STF", "n": "208", "texto": "O assistente do Ministério Público não pode recorrer, extraordinariamente, de decisão concessiva de \"habeas corpus\".", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 103.", "situacao": "Vigente", "obs": "Veja Súmula 210.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula208/false"}, {"tribunal": "STF", "n": "209", "texto": "O salário-produção, como outras modalidades de salário-prêmio, é devido, desde que verificada a condição a que estiver subordinado, e não pode ser suprimido unilateralmente, pelo empregador, quando pago com habitualidade.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 103.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula209/false"}, {"tribunal": "STF", "n": "210", "texto": "O assistente do Ministério Público pode recorrer, inclusive extraordinariamente, na ação penal, nos casos dos arts. 584, § 1º, e 598 do Cód. de Proc. Penal.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 104.", "situacao": "Vigente", "obs": "Veja Súmula 208.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula210/false"}, {"tribunal": "STF", "n": "211", "texto": "Contra a decisão proferida sôbre o agravo no auto do processo, por ocasião do julgamento da apelação, não se admitem embargos infringentes ou de nulidade.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 104.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula211/false"}, {"tribunal": "STF", "n": "212", "texto": "Tem direito ao adicional de serviço perigoso o empregado de posto de revenda de combustível líquido.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 104.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula212/false"}, {"tribunal": "STF", "n": "213", "texto": "É devido o adicional de serviço noturno, ainda que sujeito o empregado ao regime de revezamento.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 104.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula213/false"}, {"tribunal": "STF", "n": "214", "texto": "A duração legal da hora de serviço noturno (52 minutos e trinta segundos) constitui vantagem suplementar que não dispensa o salário adicional.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 105.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula214/false"}, {"tribunal": "STF", "n": "215", "texto": "Conta-se a favor de empregado readmitido o tempo de serviço anterior, salvo se houver sido despedido por falta grave ou tiver recebido a indenização legal.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 105.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula215/false"}, {"tribunal": "STF", "n": "216", "texto": "Para decretação da absolvição de instância pela paralisação do processo por mais de trinta dias, é necessário que o autor, previamente intimado, não promova o andamento da causa.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 106.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula216/false"}, {"tribunal": "STF", "n": "217", "texto": "Tem direito de retornar ao emprego, ou ser indenizado em caso de recusa do empregador, o aposentado que recupera a capacidade de trabalho dentro de cinco anos, a contar da aposentadoria, que se torna definitiva após êsse prazo.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 106.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula217/false"}, {"tribunal": "STF", "n": "218", "texto": "É competente o Juízo da Fazenda Nacional da capital do Estado, e não o da situação da coisa, para a desapropriação promovida por emprêsa de energia elétrica, se a União Federal intervém como assistente.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 106.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula218/false"}, {"tribunal": "STF", "n": "219", "texto": "Para a indenização devida a empregado que tinha direito a ser readmitido, e não foi, levam-se em conta as vantagens advindas à sua categoria no período do afastamento.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 107.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula219/false"}, {"tribunal": "STF", "n": "220", "texto": "A indenização devida a empregado estável, que não é readmitido, ao cessar sua aposentadoria, deve ser paga em dôbro.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 107.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula220/false"}, {"tribunal": "STF", "n": "221", "texto": "A transferência de estabelecimento, ou a sua extinção parcial, por motivo que não seja de fôrça maior, não justifica a transferência de empregado estável.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 108.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula221/false"}, {"tribunal": "STF", "n": "222", "texto": "O princípio da identidade física do juiz não é aplicável às Juntas de Conciliação e Julgamento da Justiça do Trabalho.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 108.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula222/false"}, {"tribunal": "STF", "n": "223", "texto": "Concedida isenção de custas ao empregado, por elas não responde o sindicato que o representa em juízo.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 108.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula223/false"}, {"tribunal": "STF", "n": "224", "texto": "Os juros da mora, nas reclamações trabalhistas, são contados desde a notificação inicial.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 109.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula224/false"}, {"tribunal": "STF", "n": "225", "texto": "Não é absoluto o valor probatório das anotações da carteira profissional.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 109.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula225/false"}, {"tribunal": "STF", "n": "226", "texto": "Na ação de desquite, os alimentos são devidos desde a inicial e não da data da decisão que os concede.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 109.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula226/false"}, {"tribunal": "STF", "n": "227", "texto": "A concordata do empregador não impede a execução de crédito nem a reclamação de empregado na Justiça do Trabalho.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 109.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula227/false"}, {"tribunal": "STF", "n": "228", "texto": "Não é provisória a execução na pendência de recurso extraordinário, ou de agravo destinado a fazê-lo admitir.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 110.", "situacao": "Vigente", "obs": "Veja RE 84334 (DJ de 08/07/1976) e RE 82902 (DJ de 08/07/1976).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula228/false"}, {"tribunal": "STF", "n": "229", "texto": "A indenização acidentária não exclui a do direito comum, em caso de dolo ou culpa grave do empregador.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 110.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula229/false"}, {"tribunal": "STF", "n": "230", "texto": "A prescrição da ação de acidente do trabalho conta-se do exame pericial que comprovar a enfermidade ou verificar a natureza da incapacidade.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 111.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula230/false"}, {"tribunal": "STF", "n": "231", "texto": "O revel, em processo cível, pode produzir provas, desde que compareça em tempo oportuno.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 111.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula231/false"}, {"tribunal": "STF", "n": "232", "texto": "Em caso de acidente do trabalho, são devidas diárias até doze meses, as quais não se confundem com a indenização acidentária nem com o auxílio-enfermidade.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 111.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula232/false"}, {"tribunal": "STF", "n": "233", "texto": "Salvo em caso de divergência qualificada (L. 623, de 1949), não cabe recurso de embargos contra decisão que nega provimento a agravo ou não conhece de recurso extraordinário, ainda que por maioria de votos.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 112.", "situacao": "Vigente", "obs": "- Veja Súmula 599. - Veja AR 723 (DJ de 21/03/1980) e RE 38448 (DJ de 13/08/1959). - Embora na publicação da Súmula 233 conste como precedente o RE 38448, trata-se do RE 38448 EI-AgR (DJ de 24/06/1960).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula233/false"}, {"tribunal": "STF", "n": "234", "texto": "São devidos honorários de advogado em ação de acidente do trabalho julgada procedente.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 112.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula234/false"}, {"tribunal": "STF", "n": "235", "texto": "É competente para a ação de acidente do trabalho a Justiça cível comum, inclusive em segunda instância, ainda que seja parte autarquia seguradora.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 112.", "situacao": "Vigente", "obs": "- Veja Súmula 501. - Veja CC 7204 (DJ de 09/12/2005).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula235/false"}, {"tribunal": "STF", "n": "236", "texto": "Em ação de acidente do trabalho, a autarquia seguradora não tem isenção de custas.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 113.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula236/false"}, {"tribunal": "STF", "n": "237", "texto": "O usucapião pode ser argüído em defesa.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 113.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula237/false"}, {"tribunal": "STF", "n": "238", "texto": "Em caso de acidente do trabalho, a multa pelo retardamento da liquidação é exigível do segurador sub-rogado, ainda que autarquia.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 113.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula238/false"}, {"tribunal": "STF", "n": "239", "texto": "Decisão que declara indevida a cobrança do impôsto em determinado exercício não faz coisa julgada em relação aos posteriores.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 114.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula239/false"}, {"tribunal": "STF", "n": "240", "texto": "O depósito para recorrer, em ação de acidente do trabalho, é exigível do segurador sub-rogado, ainda que autarquia.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 114.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula240/false"}, {"tribunal": "STF", "n": "241", "texto": "A contribuição previdenciária incide sôbre o abono incorporado ao salário.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 114.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula241/false"}, {"tribunal": "STF", "n": "242", "texto": "O agravo no auto do processo deve ser apreciado, no julgamento da apelação, ainda que o agravante não tenha apelado.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 115.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula242/false"}, {"tribunal": "STF", "n": "243", "texto": "Em caso de dupla aposentadoria, os proventos a cargo do IAPFESP não são equiparáveis aos pagos pelo Tesouro Nacional, mas calculados à base da média salarial nos últimos doze meses de serviço.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 115.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula243/false"}, {"tribunal": "STF", "n": "244", "texto": "A importação de máquinas de costura está isenta do impôsto de consumo.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 115.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula244/false"}, {"tribunal": "STF", "n": "245", "texto": "A imunidade parlamentar não se estende ao co-réu sem essa prerrogativa.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 116.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula245/false"}, {"tribunal": "STF", "n": "246", "texto": "Comprovado não ter havido fraude, não se configura o crime de emissão de cheque sem fundos.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 116.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula246/false"}, {"tribunal": "STF", "n": "247", "texto": "O relator não admitirá os embargos da L. 623, de 19.2.49, nem deles conhecerá o Supremo Tribunal Federal, quando houver jurisprudência firme do Plenário no mesmo sentido da decisão embargada.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 116.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula247/false"}, {"tribunal": "STF", "n": "248", "texto": "É competente, originariamente, o Supremo Tribunal Federal, para mandado de segurança contra ato do Tribunal de Contas da União.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 117.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula248/false"}, {"tribunal": "STF", "n": "249", "texto": "É competente o Supremo Tribunal Federal para a ação rescisória, quando, embora não tendo conhecido do recurso extraordinário, ou havendo negado provimento ao agravo, tiver apreciado a questão federal controvertida.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 117.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula249/false"}, {"tribunal": "STF", "n": "250", "texto": "A intervenção da União desloca o processo do juízo cível comum para o fazendário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 117.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula250/false"}, {"tribunal": "STF", "n": "251", "texto": "Responde a Rêde Ferroviária Federal S.A. perante o fôro comum e não perante o juízo especial da Fazenda Nacional, a menos que a União intervenha na causa.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 118.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula251/false"}, {"tribunal": "STF", "n": "252", "texto": "Na ação rescisória, não estão impedidos juízes que participaram do julgamento rescindendo.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 118.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula252/false"}, {"tribunal": "STF", "n": "253", "texto": "Nos embargos da L. 623, de 19.2.49, no Supremo Tribunal Federal, a divergência somente será acolhida, se tiver sido indicada na petição de recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 118.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula253/false"}, {"tribunal": "STF", "n": "254", "texto": "Incluem-se os juros moratórios na liquidação, embora omisso o pedido inicial ou a condenação.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 119.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula254/false"}, {"tribunal": "STF", "n": "255", "texto": "Sendo ilíquida a obrigação, os juros moratórios, contra a Fazenda Pública, incluídas as autarquias, são contados do trânsito em julgado da sentença de liquidação.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 119.", "situacao": "Vigente", "obs": "Veja RE 74244 EDv (DJ de 02/01/1974).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula255/false"}, {"tribunal": "STF", "n": "256", "texto": "É dispensável pedido expresso para condenação do réu em honorários, com fundamento nos arts. 63 ou 64 do Cód. de Proc. Civil.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 119.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula256/false"}, {"tribunal": "STF", "n": "257", "texto": "São cabíveis honorários de advogado na ação regressiva do segurador contra o causador do dano.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 120.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula257/false"}, {"tribunal": "STF", "n": "258", "texto": "É admissível reconvenção em ação declaratória.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 120.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula258/false"}, {"tribunal": "STF", "n": "259", "texto": "Para produzir efeito em juízo não é necessária a inscrição, no registro público, de documentos de procedência estrangeira, autenticados por via consular.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 120.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula259/false"}, {"tribunal": "STF", "n": "260", "texto": "O exame de livros comerciais, em ação judicial, fica limitado às transações entre os litigantes.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 121.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula260/false"}, {"tribunal": "STF", "n": "261", "texto": "Para a ação de indenização, em caso de avaria, é dispensável que a vistoria se faça judicialmente.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 121.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula261/false"}, {"tribunal": "STF", "n": "262", "texto": "Não cabe medida possessória liminar para liberação alfandegária de automóvel.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 121.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula262/false"}, {"tribunal": "STF", "n": "263", "texto": "O possuidor deve ser citado pessoalmente para a ação de usucapião.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 121.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula263/false"}, {"tribunal": "STF", "n": "264", "texto": "Verifica-se a prescrição intercorrente pela paralisação da ação rescisória por mais de cinco anos.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 122.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula264/false"}, {"tribunal": "STF", "n": "265", "texto": "Na apuração de haveres não prevalece o balanço não aprovado pelo sócio falecido, excluído ou que se retirou.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 122.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula265/false"}, {"tribunal": "STF", "n": "266", "texto": "Não cabe mandado de segurança contra lei em tese.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 122.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula266/false"}, {"tribunal": "STF", "n": "267", "texto": "Não cabe mandado de segurança contra ato judicial passível de recurso ou correição.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 123.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula267/false"}, {"tribunal": "STF", "n": "268", "texto": "Não cabe mandado de segurança contra decisão judicial com trânsito em julgado.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 123.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula268/false"}, {"tribunal": "STF", "n": "269", "texto": "O mandado de segurança não é substitutivo de ação de cobrança.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 124.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula269/false"}, {"tribunal": "STF", "n": "270", "texto": "Não cabe mandado de segurança para impugnar enquadramento da L. 3.780, de 12.7.60, que envolva exame de prova ou de situação funcional complexa.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 124.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula270/false"}, {"tribunal": "STF", "n": "271", "texto": "Concessão de mandado de segurança não produz efeitos patrimoniais em relação a período pretérito, os quais devem ser reclamados administrativamente ou pela via judicial própria.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 124.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula271/false"}, {"tribunal": "STF", "n": "272", "texto": "Não se admite como ordinário recurso extraordinário de decisão denegatória de mandado de segurança.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 125.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula272/false"}, {"tribunal": "STF", "n": "273", "texto": "Nos embargos da L. 623, de 19.2.49, a divergência sôbre questão prejudicial ou preliminar, suscitada após a interposição do recurso extraordinário, ou do agravo, somente será acolhida se o acórdão-padrão fôr anterior à decisão embargada.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 125.", "situacao": "Vigente", "obs": "Veja Súmula 598.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula273/false"}, {"tribunal": "STF", "n": "274", "texto": "É inconstitucional a taxa de serviço contra fogo cobrada pelo Estado de Pernambuco. (Revogada)", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 125. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Cancelada", "obs": "A Súmula 274 foi revogada pela Súmula 549.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula274/false"}, {"tribunal": "STF", "n": "275", "texto": "Está sujeita a recurso \"ex officio\" sentença concessiva de reajustamento pecuário anterior à vigência da L. 2.804, de 25.6.56.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 126.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula275/false"}, {"tribunal": "STF", "n": "276", "texto": "Não cabe recurso de revista em ação executiva fiscal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 126.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula276/false"}, {"tribunal": "STF", "n": "277", "texto": "São cabíveis embargos, em favor da Fazenda Pública, em ação executiva fiscal, não sendo unânime a decisão.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 126.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula277/false"}, {"tribunal": "STF", "n": "278", "texto": "São cabíveis embargos em ação executiva fiscal contra decisão reformatória da de primeira instância, ainda que unânime.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 127.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula278/false"}, {"tribunal": "STF", "n": "279", "texto": "Para simples reexame de prova não cabe recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 127.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula279/false"}, {"tribunal": "STF", "n": "280", "texto": "Por ofensa a direito local não cabe recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 127.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula280/false"}, {"tribunal": "STF", "n": "281", "texto": "É inadmissível o recurso extraordinário, quando couber na Justiça de origem, recurso ordinário da decisão impugnada.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 128.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula281/false"}, {"tribunal": "STF", "n": "282", "texto": "É inadmissível o recurso extraordinário, quando não ventilada, na decisão recorrida, a questão federal suscitada.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 128.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula282/false"}, {"tribunal": "STF", "n": "283", "texto": "É inadmissível o recurso extraordinário, quando a decisão recorrida assenta em mais de um fundamento suficiente e o recurso não abrange todos êles.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 128.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula283/false"}, {"tribunal": "STF", "n": "284", "texto": "É inadmissível o recurso extraordinário, quando a deficiência na sua fundamentação não permitir a exata compreensão da controvérsia.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 129.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula284/false"}, {"tribunal": "STF", "n": "285", "texto": "Não sendo razoável a argüição de inconstitucionalidade, não se conhece do recurso extraordinário fundado na letra c do art. 101, III, da Constituição Federal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 129.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula285/false"}, {"tribunal": "STF", "n": "286", "texto": "Não se conhece do recurso extraordinário fundado em divergência jurisprudencial, quando a orientação do plenário do Supremo Tribunal Federal já se firmou no mesmo sentido da decisão recorrida.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 129.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula286/false"}, {"tribunal": "STF", "n": "287", "texto": "Nega-se provimento ao agravo, quando a deficiência na sua fundamentação, ou na do recurso extraordinário, não permitir a exata compreensão da controvérsia.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 130.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula287/false"}, {"tribunal": "STF", "n": "288", "texto": "Nega-se provimento a agravo para subida de recurso extraordinário, quando faltar no traslado o despacho agravado, a decisão recorrida, a petição de recurso extraordinário ou qualquer peça essencial à compreensão da controvérsia.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 130.", "situacao": "Vigente", "obs": "Veja Súmula 639.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula288/false"}, {"tribunal": "STF", "n": "289", "texto": "O provimento do agravo por uma das Turmas do Supremo Tribunal Federal ainda que sem ressalva, não prejudica a questão do cabimento do recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 130.", "situacao": "Vigente", "obs": "Veja Súmula 300.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula289/false"}, {"tribunal": "STF", "n": "290", "texto": "Nos embargos da L. 623, de 19.2.49, a prova de divergência far-se-á por certidão, ou mediante indicação do \"Diário da Justiça\" ou de repertório de jurisprudência autorizado, que a tenha publicado, com a transcrição do trecho que configure a divergência, mencionadas as circunstâncias que identifiquem ou assemelhem os casos confrontados.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 131.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula290/false"}, {"tribunal": "STF", "n": "291", "texto": "No recurso extraordinário pela letra \"d\" do art. 101, n. III, da Constituição, a prova do dissídio jurisprudencial far-se-á por certidão, ou mediante indicação do \"Diário da Justiça\" ou de repertório de jurisprudência autorizado, com a transcrição do trecho que configure a divergência, mencionadas as circunstâncias que identifiquem ou assemelhem os casos confrontados.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 131.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula291/false"}, {"tribunal": "STF", "n": "292", "texto": "Interposto o recurso extraordinário por mais de um dos fundamentos indicados no art. 101, n. III, da Constituição, a admissão apenas por um dêles não prejudica o seu conhecimento por qualquer dos outros.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 131.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula292/false"}, {"tribunal": "STF", "n": "293", "texto": "São inadmissíveis embargos infringentes contra decisão em matéria constitucional submetida ao plenário dos Tribunais.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 132.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula293/false"}, {"tribunal": "STF", "n": "294", "texto": "São inadmissíveis embargos infringentes contra decisão do Supremo Tribunal Federal em mandado de segurança.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 132.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula294/false"}, {"tribunal": "STF", "n": "295", "texto": "São inadmissíveis embargos infringentes contra decisão unânime do Supremo Tribunal Federal em ação rescisória.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 132.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula295/false"}, {"tribunal": "STF", "n": "296", "texto": "São inadmissíveis embargos infringentes sôbre matéria não ventilada, pela Turma, no julgamento do recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 133.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula296/false"}, {"tribunal": "STF", "n": "297", "texto": "Oficiais e praças das milícias dos Estados, no exercício de função policial civil, não são considerados militares para efeitos penais, sendo competente a Justiça comum para julgar os crimes cometidos por ou contra êles.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 133.", "situacao": "Vigente", "obs": "Veja HC 82142 (DJ de 12/09/2003) e RHC 56049 (DJ de 30/06/1978).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula297/false"}, {"tribunal": "STF", "n": "298", "texto": "O legislador ordinário só pode sujeitar civis à Justiça Militar, em tempo de paz, nos crimes contra a segurança externa do país ou as instituições militares.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 134.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula298/false"}, {"tribunal": "STF", "n": "299", "texto": "O recurso ordinário e o extraordinário interpostos no mesmo processo de mandado de segurança, ou de \"habeas corpus\", serão julgados conjuntamente pelo Tribunal Pleno.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 134.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula299/false"}, {"tribunal": "STF", "n": "300", "texto": "São incabíveis os embargos da L. 623, de 19.2.49, contra provimento de agravo para subida de recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 134.", "situacao": "Vigente", "obs": "Veja Súmula 599.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula300/false"}, {"tribunal": "STF", "n": "301", "texto": "Por crime de responsabilidade, o procedimento penal contra Prefeito Municipal fica condicionado ao seu afastamento do cargo por \"impeachment\", ou à cessação do exercício por outro motivo. (Cancelada)", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 135.", "situacao": "Cancelada", "obs": "A Súmula 301 foi cancelada no julgamento do RHC 49038 (DJ de 19/11/1971).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula301/false"}, {"tribunal": "STF", "n": "302", "texto": "Está isenta da taxa de previdência social a importação de petróleo bruto.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 135.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula302/false"}, {"tribunal": "STF", "n": "303", "texto": "Não é devido o impôsto federal de sêlo em contrato firmado com autarquia anteriormente à vigência da Emenda Constitucional nº 5, de 21.11.61.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 135.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula303/false"}, {"tribunal": "STF", "n": "304", "texto": "Decisão denegatória de mandado de segurança, não fazendo coisa julgada contra o impetrante, não impede o uso da ação própria.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 136.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula304/false"}, {"tribunal": "STF", "n": "305", "texto": "Acordo de desquite ratificado por ambos os cônjuges não é retratável unilateralmente.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 136.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula305/false"}, {"tribunal": "STF", "n": "306", "texto": "As taxas de recuperação econômica e de assistência hospitalar de Minas Gerais são legítimas, quando incidem sôbre matéria tributável pelo Estado.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 137. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula306/false"}, {"tribunal": "STF", "n": "307", "texto": "É devido o adicional de serviço insalubre, calculado à base do salário mínimo da região, ainda que a remuneração contratual seja superior ao salário mínimo acrescido da taxa de insalubridade.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 137.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula307/false"}, {"tribunal": "STF", "n": "308", "texto": "A taxa de despacho aduaneiro, sendo adicional do impôsto de importação, não incide sôbre borracha importada com isenção daquele impôsto.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 137. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": "Veja Súmula 130 e Súmula 131.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula308/false"}, {"tribunal": "STF", "n": "309", "texto": "A taxa de despacho aduaneiro, sendo adicional do impôsto de importação, não está compreendida na isenção do impôsto de consumo para automóvel usado trazido do exterior pelo proprietário.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 138. Republicação: DJ de 06/07/1964, p. 2185; DJ de 07/07/1964, p. 2201; DJ de 08/07/1964, p. 2241.", "situacao": "Vigente", "obs": "Veja Súmula 86.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula309/false"}, {"tribunal": "STF", "n": "310", "texto": "Quando a intimação tiver lugar na sexta-feira, ou a publicação com efeito de intimação fôr feita nesse dia, o prazo judicial terá início na segunda-feira imediata, salvo se não houver expediente, caso em que começará no primeiro dia útil que se seguir.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 138.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula310/false"}, {"tribunal": "STF", "n": "311", "texto": "No típico acidente do trabalho, a existência de ação judicial não exclui a multa pelo retardamento da liquidação.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 139.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula311/false"}, {"tribunal": "STF", "n": "312", "texto": "Músico integrante de orquestra da emprêsa, com atuação permanente e vínculo de subordinação, está sujeito a legislação geral do trabalho, e não à especial dos artistas.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 139.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula312/false"}, {"tribunal": "STF", "n": "313", "texto": "Provada a identidade entre o trabalho diurno e o noturno, é devido o adicional, quanto a este, sem a limitação do art. 73, § 3º, da C.L.T., independentemente da natureza da atividade do empregador.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 139.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula313/false"}, {"tribunal": "STF", "n": "314", "texto": "Na composição do dano por acidente do trabalho, ou de transporte, não é contrário à lei tomar para base da indenização o salário do tempo da perícia ou da sentença.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 140.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula314/false"}, {"tribunal": "STF", "n": "315", "texto": "Indispensável o traslado das razões da revista, para julgamento, pelo Tribunal Superior do Trabalho, do agravo para sua admissão.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 140.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula315/false"}, {"tribunal": "STF", "n": "316", "texto": "A simples adesão a greve não constitui falta grave.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 140.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula316/false"}, {"tribunal": "STF", "n": "317", "texto": "São improcedentes os embargos declaratórios, quando não pedida a declaração do julgado anterior, em que se verificou a omissão.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 141.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula317/false"}, {"tribunal": "STF", "n": "318", "texto": "É legítima a cobrança, em 1962, pela municipalidade de São Paulo, do impôsto de indústrias e profissões, consoante as leis 5.917 e 5.919, de 1961 (aumento anterior à vigência do orçamento e incidência do tributo sôbre o movimento econômico do contribuinte).", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 141.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula318/false"}, {"tribunal": "STF", "n": "319", "texto": "O prazo do recurso ordinário para o Supremo Tribunal Federal, em \"habeas corpus\" ou mandado de segurança, é de cinco dias.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 142.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula319/false"}, {"tribunal": "STF", "n": "320", "texto": "A apelação despachada pelo juiz no prazo legal não fica prejudicada pela demora da juntada, por culpa do cartório.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 142.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula320/false"}, {"tribunal": "STF", "n": "321", "texto": "A constituição estadual pode estabelecer a irredutibilidade dos vencimentos do Ministério Público.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 142.", "situacao": "Vigente", "obs": "Veja Rp 1428 (DJ de 17/02/1989).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula321/false"}, {"tribunal": "STF", "n": "322", "texto": "Não terá seguimento pedido ou recurso dirigido ao Supremo Tribunal Federal, quando manifestamente incabível, ou apresentado fora do prazo, ou quando for evidente a incompetência do Tribunal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 143.", "situacao": "Vigente", "obs": "Veja RE 83278 (DJ de 08/07/1976).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula322/false"}, {"tribunal": "STF", "n": "323", "texto": "É inadmissível a apreensão de mercadorias como meio coercitivo para pagamento de tributos.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 143.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula323/false"}, {"tribunal": "STF", "n": "324", "texto": "A imunidade do art. 31, V, da Constituição Federal não compreende as taxas.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 144.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula324/false"}, {"tribunal": "STF", "n": "325", "texto": "As emendas ao regimento do Supremo Tribunal Federal, sôbre julgamento de questão constitucional, aplicam-se aos pedidos ajuizados e aos recursos interpostos anteriormente a sua aprovação.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 144.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula325/false"}, {"tribunal": "STF", "n": "326", "texto": "É legítima a incidência do impôsto de transmissão \"inter vivos\" sôbre a transferência do domínio útil.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 144.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula326/false"}, {"tribunal": "STF", "n": "327", "texto": "O direito trabalhista admite a prescrição intercorrente.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 145.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula327/false"}, {"tribunal": "STF", "n": "328", "texto": "É legítima a incidência do impôsto de transmissão inter vivos sôbre a doação de imóvel.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 145.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula328/false"}, {"tribunal": "STF", "n": "329", "texto": "O impôsto de transmissão \"inter vivos\" não incide sôbre a transferência de ações de sociedade imobiliária.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 145.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula329/false"}, {"tribunal": "STF", "n": "330", "texto": "O Supremo Tribunal Federal não é competente para conhecer de mandado de segurança contra atos dos Tribunais de Justiça dos Estados.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 146.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula330/false"}, {"tribunal": "STF", "n": "331", "texto": "É legítima a incidência do impôsto de transmissão \"causa mortis\" no inventário por morte presumida.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 146.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula331/false"}, {"tribunal": "STF", "n": "332", "texto": "É legítima a incidência do impôsto de vendas e consignações sôbre a parcela do preço correspondente aos ágios cambiais.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 146.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula332/false"}, {"tribunal": "STF", "n": "333", "texto": "Está sujeita ao impôsto de vendas e consignações a venda realizada por invernista não qualificado como pequeno produtor.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 146.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula333/false"}, {"tribunal": "STF", "n": "334", "texto": "É legítima a cobrança, ao empreiteiro, do impôsto de vendas e consignações, sôbre o valor dos materiais empregados, quando a empreitada não for apenas de lavor.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 147.", "situacao": "Vigente", "obs": "Embora na publicação da Súmula 334 conste como precedente o RE 7242 (DJ de 16/08/1957), trata-se da ACi 7242 (ADJ 24/03/1942).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula334/false"}, {"tribunal": "STF", "n": "335", "texto": "É válida a cláusula de eleição do fôro para os processos oriundos do contrato.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 147.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula335/false"}, {"tribunal": "STF", "n": "336", "texto": "A imunidade da autarquia financiadora, quanto ao contrato de financiamento, não se estende à compra e venda entre particulares, embora constantes os dois atos de um só instrumento.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 147.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula336/false"}, {"tribunal": "STF", "n": "337", "texto": "A controvérsia entre o empregador e o segurador não suspende o pagamento devido ao empregado por acidente do trabalho.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 148.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula337/false"}, {"tribunal": "STF", "n": "338", "texto": "Não cabe ação rescisória no âmbito da justiça do trabalho.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 148.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula338/false"}, {"tribunal": "STF", "n": "339", "texto": "Não cabe ao Poder Judiciário, que não tem função legislativa, aumentar vencimentos de servidores públicos sob fundamento de isonomia.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 148.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 37.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula339/false"}, {"tribunal": "STF", "n": "340", "texto": "Desde a vigência do Código Civil, os bens dominicais, como os demais bens públicos, não podem ser adquiridos por usucapião.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 149.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula340/false"}, {"tribunal": "STF", "n": "341", "texto": "É presumida a culpa do patrão ou comitente pelo ato culposo do empregado ou preposto.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 149.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula341/false"}, {"tribunal": "STF", "n": "342", "texto": "Cabe agravo no auto do processo, e não agravo de petição, do despacho que não admite a reconvenção.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 149.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula342/false"}, {"tribunal": "STF", "n": "343", "texto": "Não cabe ação rescisória por ofensa a literal disposição de lei, quando a decisão rescindenda se tiver baseado em texto legal de interpretação controvertida nos tribunais.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 150.", "situacao": "Vigente", "obs": "Veja AI 460439 AgR (DJ de 09/03/2007).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula343/false"}, {"tribunal": "STF", "n": "344", "texto": "Sentença de primeira instância concessiva de \"habeas corpus\", em caso de crime praticado em detrimento de bens, serviços ou interesses da União, está sujeita a recurso \"ex officio\".", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 150.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula344/false"}, {"tribunal": "STF", "n": "345", "texto": "Na chamada desapropriação indireta, os juros compensatórios são devidos a partir da perícia, desde que tenha atribuído valor atual ao imóvel.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 150.", "situacao": "Vigente", "obs": "- Veja Súmula 164 e Súmula 618. - Veja ACO 297 (DJ de 13/09/1985), RE 48540 (DJ de 01/07/1970), RE 52441 EDv (DJ de 05/06/1970) e RE 47934 EDv (DJ de 30/05/1969).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula345/false"}, {"tribunal": "STF", "n": "346", "texto": "A administração pública pode declarar a nulidade dos seus próprios atos.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 151.", "situacao": "Vigente", "obs": "Veja Súmula 6 e Súmula 473.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula346/false"}, {"tribunal": "STF", "n": "347", "texto": "O Tribunal de Contas, no exercício de suas atribuições, pode apreciar a constitucionalidade das leis e dos atos do poder público.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 151.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula347/false"}, {"tribunal": "STF", "n": "348", "texto": "É constitucional a criação de taxa de construção, conservação e melhoramento de estradas.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 152.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula348/false"}, {"tribunal": "STF", "n": "349", "texto": "A prescrição atinge somente as prestações de mais de dois anos, reclamadas com fundamento em decisão normativa da Justiça do Trabalho, ou em convenção coletiva de trabalho, quando não estiver em causa a própria validade de tais atos.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 152.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula349/false"}, {"tribunal": "STF", "n": "350", "texto": "O impôsto de indústrias e profissões não é exigível de empregado, por falta de autonomia na sua atividade profissional.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 152.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula350/false"}, {"tribunal": "STF", "n": "351", "texto": "É nula a citação por edital de réu prêso na mesma unidade da Federação em que o juiz exerce a sua jurisdição.", "vinculante": false, "materia": "", "ramo": "", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 153.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula351/false"}, {"tribunal": "STF", "n": "352", "texto": "Não é nulo o processo penal por falta de nomeação de curador ao réu menor que teve a assistência de defensor dativo.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 153.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula352/false"}, {"tribunal": "STF", "n": "353", "texto": "São incabíveis os embargos da L. 623, de 19.2.49, com fundamento em divergência entre decisões da mesma Turma do Supremo Tribunal Federal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 153.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula353/false"}, {"tribunal": "STF", "n": "354", "texto": "Em caso de embargos infringentes parciais, é definitiva a parte da decisão embargada em que não houve divergência na votação.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 154.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula354/false"}, {"tribunal": "STF", "n": "355", "texto": "Em caso de embargos infringentes parciais, é tardio o recurso extraordinário interposto após o julgamento dos embargos, quanto à parte da decisão embargada que não fôra por eles abrangida.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 154.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula355/false"}, {"tribunal": "STF", "n": "356", "texto": "O ponto omisso da decisão, sôbre o qual não foram opostos embargos declaratórios, não pode ser objeto de recurso extraordinário, por faltar o requisito do prequestionamento.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 154.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula356/false"}, {"tribunal": "STF", "n": "357", "texto": "É lícita a convenção pela qual o locador renuncia, durante a vigência do contrato, à ação revisional do art. 31 do Decreto 24.150, de 20.4.34.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 155.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula357/false"}, {"tribunal": "STF", "n": "358", "texto": "O servidor público em disponibilidade tem direito aos vencimentos integrais do cargo.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 155.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula358/false"}, {"tribunal": "STF", "n": "359", "texto": "Ressalvada a revisão prevista em lei, os proventos da inatividade regulam-se pela lei vigente ao tempo em que o militar, ou o servidor civil, reuniu os requisitos necessários. (Alterada)", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 155.", "situacao": "Alterada", "obs": "A Súmula 359 foi alterada no julgamento dos RE 72509 ED-EDv (DJ de 30/03/1973).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula359/false"}, {"tribunal": "STF", "n": "360", "texto": "Não há prazo de decadência para a representação de inconstitucionalidade prevista no art. 8º, parágrafo único, da Constituição Federal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 156.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula360/false"}, {"tribunal": "STF", "n": "361", "texto": "No processo penal, é nulo o exame realizado por um só perito, considerando-se impedido o que tiver funcionado, anteriormente, na diligência de apreensão.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 156.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula361/false"}, {"tribunal": "STF", "n": "362", "texto": "A condição de ter o clube sede própria para a prática de jôgo lícito não o obriga a ser proprietário do imóvel em que tem sede.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 156.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula362/false"}, {"tribunal": "STF", "n": "363", "texto": "A pessoa jurídica de direito privado pode ser demandada no domicílio da agência, ou estabelecimento, em que se praticou o ato.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 157.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula363/false"}, {"tribunal": "STF", "n": "364", "texto": "Enquanto o Estado da Guanabara não tiver Tribunal Militar de segunda instância, o Tribunal de Justiça é competente para julgar os recursos das decisões da auditoria da Polícia Militar.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 157.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula364/false"}, {"tribunal": "STF", "n": "365", "texto": "Pessoa jurídica não tem legitimidade para propor ação popular.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 157.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula365/false"}, {"tribunal": "STF", "n": "366", "texto": "Não é nula a citação por edital que indica o dispositivo da lei penal, embora não transcreva a denúncia ou queixa, ou não resuma os fatos em que se baseia.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 158.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula366/false"}, {"tribunal": "STF", "n": "367", "texto": "Concede-se liberdade ao extraditando que não fôr retirado do país no prazo do art. 16 do Decreto-lei. 394, de 28.4.38.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 158.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula367/false"}, {"tribunal": "STF", "n": "368", "texto": "Não há embargos infringentes no processo de reclamação.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 158.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula368/false"}, {"tribunal": "STF", "n": "369", "texto": "Julgados do mesmo Tribunal não servem para fundamentar o recurso extraordinário por divergência jurisprudencial.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 159.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula369/false"}, {"tribunal": "STF", "n": "370", "texto": "Julgada improcedente a ação renovatória da locação, terá o locatário, para desocupar o imóvel, o prazo de seis meses, acrescido de tantos meses quantos forem os anos da ocupação, até o limite total de dezoito meses.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "13/12/1963", "pub": "Súmula da Jurisprudência Predominante do Supremo Tribunal Federal - Anexo ao Regimento Interno. Edição: Imprensa Nacional, 1964, p. 159.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula370/false"}, {"tribunal": "STF", "n": "371", "texto": "Ferroviário, que foi admitido como servidor autárquico, não tem direito a dupla aposentadoria.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula371/false"}, {"tribunal": "STF", "n": "372", "texto": "A L. 2.752, de 10.4.56, sôbre dupla aposentadoria, aproveita, quando couber, a servidores aposentados antes de sua publicação.", "vinculante": false, "materia": "", "ramo": "", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula372/false"}, {"tribunal": "STF", "n": "373", "texto": "Servidor nomeado após aprovação no curso de capacitação policial, instituído na Polícia do Distrito Federal, em 1941, preenche o requisito da nomeação por concurso a que se referem as Leis 705, de 16.5.49 e 1.639, de 14.7.52.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula373/false"}, {"tribunal": "STF", "n": "374", "texto": "Na retomada para construção mais útil, não é necessário que a obra tenha sido ordenada pela autoridade pública.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula374/false"}, {"tribunal": "STF", "n": "375", "texto": "Não renovada a locação regida pelo D. 24.150, de 20.4.34, aplica-se o direito comum e não a legislação especial do inquilinato.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula375/false"}, {"tribunal": "STF", "n": "376", "texto": "Na renovação de locação, regida pelo D. 24.150, de 20.4.34, o prazo do nôvo contrato conta-se da transcrição da decisão exequenda no Registro de Títulos e Documentos; começa, porém, da terminação do contrato anterior, se esta tiver ocorrido antes do registro.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula376/false"}, {"tribunal": "STF", "n": "377", "texto": "No regime de separação legal de bens, comunicam-se os adquiridos na constância do casamento.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula377/false"}, {"tribunal": "STF", "n": "378", "texto": "Na indenização por desapropriação incluem-se honorários do advogado do expropriado.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula378/false"}, {"tribunal": "STF", "n": "379", "texto": "No acôrdo de desquite não se admite renúncia aos alimentos, que poderão ser pleiteados ulteriormente, verificados os pressupostos legais.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula379/false"}, {"tribunal": "STF", "n": "380", "texto": "Comprovada a existência de sociedade de fato entre os concubinos, é cabível a sua dissolução judicial, com a partilha do patrimônio adquirido pelo esfôrço comum.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula380/false"}, {"tribunal": "STF", "n": "381", "texto": "Não se homologa sentença de divórcio obtida, por procuração, em país de que os cônjuges não eram nacionais.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula381/false"}, {"tribunal": "STF", "n": "382", "texto": "A vida em comum sob o mesmo teto, \"more uxorio\", não é indispensável à caracterização do concubinato.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1237; DJ de 11/05/1964, p. 1253; DJ de 12/05/1964, p. 1277.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula382/false"}, {"tribunal": "STF", "n": "383", "texto": "A prescrição em favor da Fazenda Pública recomeça a correr, por dois anos e meio, a partir do ato interruptivo, mas não fica reduzida aquém de cinco anos, embora o titular do direito a interrompa durante a primeira metade do prazo.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1238; DJ de 11/05/1964, p. 1254; DJ de 12/05/1964, p. 1278.", "situacao": "Vigente", "obs": "Não há, nos registros da Coordenadoria de Análise de Jurisprudência, informação sobre o inteiro teor do acórdão do RE 12973.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula383/false"}, {"tribunal": "STF", "n": "384", "texto": "A demissão de extranumerário do serviço público federal, equiparado a funcionário de provimento efetivo para efeito de estabilidade, é da competência do Presidente da República.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1238; DJ de 11/05/1964, p. 1254; DJ de 12/05/1964, p. 1278.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula384/false"}, {"tribunal": "STF", "n": "385", "texto": "Oficial das Fôrças Armadas só pode ser reformado, em tempo de paz, por decisão de tribunal militar permanente, ressalvada a situação especial dos atingidos pelo art. 177 da Constituição de 1937.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1238; DJ de 11/05/1964, p. 1254; DJ de 12/05/1964, p. 1278.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula385/false"}, {"tribunal": "STF", "n": "386", "texto": "Pela execução de obra musical por artistas remunerados é devido direito autoral, não exigível quando a orquestra fôr de amadores.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1238; DJ de 11/05/1964, p. 1254; DJ de 12/05/1964, p. 1278.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula386/false"}, {"tribunal": "STF", "n": "387", "texto": "A cambial emitida ou aceita com omissões, ou em branco, pode ser completada pelo credor de boa-fé antes da cobrança ou do protesto.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1238; DJ de 11/05/1964, p. 1254; DJ de 12/05/1964, p. 1278.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula387/false"}, {"tribunal": "STF", "n": "388", "texto": "O casamento da ofendida com quem não seja o ofensor faz cessar a qualidade do seu representante legal, e a ação penal só pode prosseguir por iniciativa da própria ofendida, observados os prazos legais de decadência e perempção. (Revogada)", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1238; DJ de 11/05/1964, p. 1254; DJ de 12/05/1964, p. 1278.", "situacao": "Cancelada", "obs": "A Súmula 388 foi revogada no julgamento do HC 53777 (DJ de 10/09/1976).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula388/false"}, {"tribunal": "STF", "n": "389", "texto": "Salvo limite legal, a fixação de honorários de advogado, em complemento da condenação, depende das circunstâncias da causa, não dando lugar a recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1238; DJ de 11/05/1964, p. 1254; DJ de 12/05/1964, p. 1278.", "situacao": "Vigente", "obs": "Veja Súmula 279.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula389/false"}, {"tribunal": "STF", "n": "390", "texto": "A exibição judicial de livros comerciais pode ser requerida como medida preventiva.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1238; DJ de 11/05/1964, p. 1254; DJ de 12/05/1964, p. 1278.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula390/false"}, {"tribunal": "STF", "n": "391", "texto": "O confinante certo deve ser citado, pessoalmente, para a ação de usucapião.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": "Veja Súmula 263.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula391/false"}, {"tribunal": "STF", "n": "392", "texto": "O prazo para recorrer de acórdão concessivo de segurança conta-se da publicação oficial de suas conclusões, e não da anterior ciência à autoridade para cumprimento da decisão.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": "Veja Súmula 310.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula392/false"}, {"tribunal": "STF", "n": "393", "texto": "Para requerer revisão criminal, o condenado não é obrigado a recolher-se à prisão.", "vinculante": false, "materia": "", "ramo": "", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula393/false"}, {"tribunal": "STF", "n": "394", "texto": "Cometido o crime durante o exercício funcional, prevalece a competência especial por prerrogativa de função, ainda que o inquérito ou a ação penal sejam iniciados após a cessação daquele exercício. (Cancelada)", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Cancelada", "obs": "- Veja Súmula 451. - A Súmula 394 foi cancelada nos seguintes julgamentos: Inq 687 QO (DJ de 09/11/2001), AP 315 QO (DJ de 31/10/2001), AP 319 QO (DJ de 31/10/2001), Inq 656 QO (DJ de 31/10/2001), Inq 881 QO (DJ de 31/10/2001). AP 313 QO-QO (DJ de 09/11/2001).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula394/false"}, {"tribunal": "STF", "n": "395", "texto": "Não se conhece de recurso de \"habeas corpus\" cujo objeto seja resolver sôbre o ônus das custas, por não estar mais em causa a liberdade de locomoção.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula395/false"}, {"tribunal": "STF", "n": "396", "texto": "Para a ação penal por ofensa à honra, sendo admissível a exceção da verdade quanto ao desempenho de função pública, prevalece a competência especial por prerrogativa de função, ainda que já tenha cessado o exercício funcional do ofendido.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula396/false"}, {"tribunal": "STF", "n": "397", "texto": "O poder de polícia da Câmara dos Deputados e do Senado Federal, em caso de crime cometido nas suas dependências, compreende, consoante o regimento, a prisão em flagrante do acusado e a realização do inquérito.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula397/false"}, {"tribunal": "STF", "n": "398", "texto": "O Supremo Tribunal Federal não é competente para processar e julgar, originariamente, deputado ou senador acusado de crime.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": "Veja Inq 2245 QO-QO (DJe nº 139 de 09/11/2007).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula398/false"}, {"tribunal": "STF", "n": "399", "texto": "Não cabe recurso extraordinário, por violação de lei federal, quando a ofensa alegada fôr a regimento de tribunal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula399/false"}, {"tribunal": "STF", "n": "400", "texto": "Decisão que deu razoável interpretação à lei, ainda que não seja a melhor, não autoriza recurso extraordinário pela letra \"a\" do art. 101, III, da C.F.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula400/false"}, {"tribunal": "STF", "n": "401", "texto": "Não se conhece do recurso de revista, nem dos embargos de divergência, do processo trabalhista, quando houver jurisprudência firme do Tribunal Superior do Trabalho no mesmo sentido da decisão impugnada, salvo se houver colisão com a jurisprudência do Supremo Tribunal Federal.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": "Veja Súmula 247 e Súmula 286.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula401/false"}, {"tribunal": "STF", "n": "402", "texto": "Vigia noturno tem direito a salário adicional.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": "Veja Súmula 213, Súmula 214 e Súmula 313.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula402/false"}, {"tribunal": "STF", "n": "403", "texto": "É de decadência o prazo de trinta dias para instauração do inquérito judicial, a contar da suspensão, por falta grave, de empregado estável.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula403/false"}, {"tribunal": "STF", "n": "404", "texto": "Não contrariam a Constituição os arts 3º, 22 e 27 da L. 3.244, de 14.8.57, que definem as atribuições do Conselho de Política Aduaneira quanto à tarifa flexível.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/04/1964", "pub": "DJ de 08/05/1964, p. 1239; DJ de 11/05/1964, p. 1255; DJ de 12/05/1964, p. 1279.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula404/false"}, {"tribunal": "STF", "n": "405", "texto": "Denegado o mandado de segurança pela sentença, ou no julgamento do agravo, dela interposto, fica sem efeito a liminar concedida, retroagindo os efeitos da decisão contrária.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2181; DJ de 07/07/1964, p. 2197; DJ de 08/07/1964, p. 2237.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula405/false"}, {"tribunal": "STF", "n": "406", "texto": "O estudante ou professor bolsista e o servidor público em missão de estudo satisfazem a condição da mudança de residência para o efeito de trazer automóvel do exterior, atendidos os demais requisitos legais.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2181; DJ de 07/07/1964, p. 2197; DJ de 08/07/1964, p. 2237.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula406/false"}, {"tribunal": "STF", "n": "407", "texto": "Não tem direito ao têrço de campanha o militar que não participou de operações de guerra, embora servisse na \"zona de guerra\".", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2181; DJ de 07/07/1964, p. 2197; DJ de 08/07/1964, p. 2237.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula407/false"}, {"tribunal": "STF", "n": "408", "texto": "Os servidores fazendários não têm direito a percentagem pela arrecadação de receita federal destinada ao Banco Nacional de Desenvolvimento Econômico.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2181; DJ de 07/07/1964, p. 2197; DJ de 08/07/1964, p. 2237.", "situacao": "Vigente", "obs": "Veja Súmula 30.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula408/false"}, {"tribunal": "STF", "n": "409", "texto": "Ao retomante, que tenha mais de um prédio alugado, cabe optar entre eles, salvo abuso de direito.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2181; DJ de 07/07/1964, p. 2197; DJ de 08/07/1964, p. 2237.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula409/false"}, {"tribunal": "STF", "n": "410", "texto": "Se o locador, utilizando prédio próprio para residência ou atividade comercial, pede o imóvel locado para uso próprio, diverso do que tem o por ele ocupado, não está obrigado a provar a necessidade, que se presume.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2181; DJ de 07/07/1964, p. 2197; DJ de 08/07/1964, p. 2237.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula410/false"}, {"tribunal": "STF", "n": "411", "texto": "O locatário autorizado a ceder a locação pode sublocar o imóvel.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2181; DJ de 07/07/1964, p. 2197; DJ de 08/07/1964, p. 2237.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula411/false"}, {"tribunal": "STF", "n": "412", "texto": "No compromisso de compra e venda com cláusula de arrependimento, a devolução do sinal, por quem o deu, ou a sua restituição em dôbro, por quem o recebeu, exclui indenização maior, a título de perdas e danos, salvo os juros moratórios e os encargos do processo.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2181; DJ de 07/07/1964, p. 2197; DJ de 08/07/1964, p. 2237.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula412/false"}, {"tribunal": "STF", "n": "413", "texto": "O compromisso de compra e venda de imóveis, ainda que não loteados, dá direito à execução compulsória, quando reunidos os requisitos legais.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2182; DJ de 07/07/1964, p. 2198; DJ de 08/07/1964, p. 2238.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula413/false"}, {"tribunal": "STF", "n": "414", "texto": "Não se distingue a visão direta da oblíqua na proibição de abrir janela, ou fazer terraço, eirado, ou varanda, a menos de metro e meio do prédio de outrem.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2182; DJ de 07/07/1964, p. 2198; DJ de 08/07/1964, p. 2238.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula414/false"}, {"tribunal": "STF", "n": "415", "texto": "Servidão de trânsito não titulada, mas tornada permanente, sobretudo pela natureza das obras realizadas, considera-se aparente, conferindo direito à proteção possessória.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2182; DJ de 07/07/1964, p. 2198; DJ de 08/07/1964, p. 2238.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula415/false"}, {"tribunal": "STF", "n": "416", "texto": "Pela demora no pagamento do preço da desapropriação não cabe indenização complementar além dos juros.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2182; DJ de 07/07/1964, p. 2198; DJ de 08/07/1964, p. 2238.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula416/false"}, {"tribunal": "STF", "n": "417", "texto": "Pode ser objeto de restituição, na falência, dinheiro em poder do falido, recebido em nome de outrem, ou do qual, por lei ou contrato, não tivesse êle a disponibilidade.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2182; DJ de 07/07/1964, p. 2198; DJ de 08/07/1964, p. 2238.", "situacao": "Vigente", "obs": "Veja Súmula 193 e Súmula 495.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula417/false"}, {"tribunal": "STF", "n": "418", "texto": "O empréstimo compulsório não é tributo, e sua arrecadação não está sujeita à exigência constitucional da prévia autorização orçamentária.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2182; DJ de 07/07/1964, p. 2198; DJ de 08/07/1964, p. 2238.", "situacao": "Vigente", "obs": "Veja RE 111954 (DJ de 24/06/1988).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula418/false"}, {"tribunal": "STF", "n": "419", "texto": "Os Municípios têm competência para regular o horário do comércio local, desde que não infrinjam leis estaduais ou federais válidas.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2182; DJ de 07/07/1964, p. 2198; DJ de 08/07/1964, p. 2238.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 38 e Súmula 645.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula419/false"}, {"tribunal": "STF", "n": "420", "texto": "Não se homologa sentença proferida no estrangeiro sem prova do trânsito em julgado.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula420/false"}, {"tribunal": "STF", "n": "421", "texto": "Não impede a extradição a circunstância de ser o extraditando casado com brasileira ou ter filho brasileiro.", "vinculante": false, "materia": "Internacional", "ramo": "Internacional", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula421/false"}, {"tribunal": "STF", "n": "422", "texto": "A absolvição criminal não prejudica a medida de segurança, quando couber, ainda que importe privação da liberdade.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula422/false"}, {"tribunal": "STF", "n": "423", "texto": "Não transita em julgado a sentença por haver omitido o recurso \"ex officio\", que se considera interposto \"ex lege\".", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula423/false"}, {"tribunal": "STF", "n": "424", "texto": "Transita em julgado o despacho saneador de que não houve recurso, excluídas as questões deixadas, explícita ou implicitamente, para a sentença.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula424/false"}, {"tribunal": "STF", "n": "425", "texto": "O agravo despachado no prazo legal não fica prejudicado pela demora da juntada, por culpa do cartório; nem o agravo entregue em cartório no prazo legal, embora despachado tardiamente.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": "Veja Súmula 320 e Súmula 428.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula425/false"}, {"tribunal": "STF", "n": "426", "texto": "A falta do termo específico não prejudica o agravo no auto do processo, quando oportuna a interposição por petição ou no têrmo da audiência.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": "Veja Súmula 427.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula426/false"}, {"tribunal": "STF", "n": "427", "texto": "A falta de petição de interposição não prejudica o agravo no auto do processo tomado por têrmo.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": "- Veja Súmula 426. - Veja RE 66447 (DJ de 20/02/1970).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula427/false"}, {"tribunal": "STF", "n": "428", "texto": "Não fica prejudicada a apelação entregue em cartório no prazo legal, embora despachada tardiamente.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": "Veja Súmula 320 e Súmula 425.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula428/false"}, {"tribunal": "STF", "n": "429", "texto": "A existência de recurso administrativo com efeito suspensivo não impede o uso do mandado de segurança contra omissão da autoridade.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula429/false"}, {"tribunal": "STF", "n": "430", "texto": "Pedido de reconsideração na via administrativa não interrompe o prazo para o mandado de segurança.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula430/false"}, {"tribunal": "STF", "n": "431", "texto": "É nulo o julgamento de recurso criminal, na segunda instância, sem prévia intimação, ou publicação da pauta, salvo em \"habeas corpus\".", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula431/false"}, {"tribunal": "STF", "n": "432", "texto": "Não cabe recurso extraordinário com fundamento no art. 101, III, \"d\", da Constituição Federal, quando a divergência alegada fôr entre decisões da Justiça do Trabalho.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula432/false"}, {"tribunal": "STF", "n": "433", "texto": "É competente o Tribunal Regional do Trabalho para julgar mandado de segurança contra ato de seu presidente em execução de sentença trabalhista.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula433/false"}, {"tribunal": "STF", "n": "434", "texto": "A controvérsia entre seguradores indicados pelo empregador na ação de acidente do trabalho não suspende o pagamento devido ao acidentado.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2183; DJ de 07/07/1964, p. 2199; DJ de 08/07/1964, p. 2239.", "situacao": "Vigente", "obs": "Veja Súmula 337.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula434/false"}, {"tribunal": "STF", "n": "435", "texto": "O impôsto de transmissão \"causa mortis\" pela transferência de ações é devido ao Estado em que tem sede a companhia.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2184; DJ de 07/07/1964, p. 2200; DJ de 08/07/1964, p. 2240.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula435/false"}, {"tribunal": "STF", "n": "436", "texto": "É válida a L. 4.093, de 24.10.959, do Paraná, que revogou a isenção concedida às cooperativas por lei anterior.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2184; DJ de 07/07/1964, p. 2200; DJ de 08/07/1964, p. 2240.", "situacao": "Vigente", "obs": "Veja Súmula 81 e Súmula 84.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula436/false"}, {"tribunal": "STF", "n": "437", "texto": "Está isenta da taxa de despacho aduaneiro a importação de equipamento para a indústria automobilística, segundo plano aprovado, no prazo legal, pelo órgão competente.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2184; DJ de 07/07/1964, p. 2200; DJ de 08/07/1964, p. 2240.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula437/false"}, {"tribunal": "STF", "n": "438", "texto": "É ilegítima a cobrança, em 1962, da Taxa de Educação e Saúde, de Santa Catarina, adicional do impôsto de vendas e consignações.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/06/1964", "pub": "DJ de 06/07/1964, p. 2184; DJ de 07/07/1964, p. 2200; DJ de 08/07/1964, p. 2240.", "situacao": "Vigente", "obs": "Veja Súmula 67.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula438/false"}, {"tribunal": "STF", "n": "439", "texto": "Estão sujeitos à fiscalização tributária ou previdenciária quaisquer livros comerciais, limitado o exame aos pontos objeto da investigação.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3645; DJ de 09/10/1964, p. 3665; DJ de 12/10/1964, p. 3697.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula439/false"}, {"tribunal": "STF", "n": "440", "texto": "Os benefícios da legislação federal de serviços de guerra não são exigíveis dos Estados, sem que a lei estadual assim disponha.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3645; DJ de 09/10/1964, p. 3665; DJ de 12/10/1964, p. 3697.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula440/false"}, {"tribunal": "STF", "n": "441", "texto": "O militar, que passa à inatividade com proventos integrais, não tem direito às cotas trigésimas a que se refere o Código de Vencimentos e Vantagens dos Militares.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3645; DJ de 09/10/1964, p. 3665; DJ de 12/10/1964, p. 3697.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula441/false"}, {"tribunal": "STF", "n": "442", "texto": "A inscrição do contrato de locação no Registro de Imóveis, para a validade da cláusula de vigência contra o adquirente do imóvel, ou perante terceiros, dispensa a transcrição no Registro de Títulos e Documentos.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3645; DJ de 09/10/1964, p. 3665; DJ de 12/10/1964, p. 3697.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula442/false"}, {"tribunal": "STF", "n": "443", "texto": "A prescrição das prestações anteriores ao período previsto em lei não ocorre, quando não tiver sido negado, antes daquele prazo, o próprio direito reclamado, ou a situação jurídica de que êle resulta.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3645; DJ de 09/10/1964, p. 3665; DJ de 12/10/1964, p. 3697.", "situacao": "Vigente", "obs": "Veja Súmula 349.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula443/false"}, {"tribunal": "STF", "n": "444", "texto": "Na retomada para construção mais útil, de imóvel sujeito ao D. 24.150, de 20.4.34, a indenização se limita às despesas de mudança.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3645; DJ de 09/10/1964, p. 3665; DJ de 12/10/1964, p. 3697.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula444/false"}, {"tribunal": "STF", "n": "445", "texto": "A L. 2.437, de 7.3.55, que reduz prazo prescricional, é aplicável às prescrições em curso na data de sua vigência (1.1.56), salvo quanto aos processos então pendentes.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3645; DJ de 09/10/1964, p. 3665; DJ de 12/10/1964, p. 3697.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula445/false"}, {"tribunal": "STF", "n": "446", "texto": "Contrato de exploração de jazida ou pedreira não está sujeito ao D. 24.150, de 20.4.34.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3646; DJ de 09/10/1964, p. 3666; DJ de 12/10/1964, p. 3698.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula446/false"}, {"tribunal": "STF", "n": "447", "texto": "É válida a disposição testamentária em favor de filho adulterino do testador com sua concubina.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3646; DJ de 09/10/1964, p. 3666; DJ de 12/10/1964, p. 3698.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula447/false"}, {"tribunal": "STF", "n": "448", "texto": "O prazo para o assistente recorrer, supletivamente, começa a correr imediatamente após o transcurso do prazo do Ministério Público.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3646; DJ de 09/10/1964, p. 3666; DJ de 12/10/1964, p. 3698.", "situacao": "Vigente", "obs": "Veja HC 50417 (DJ de 10/09/1973).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula448/false"}, {"tribunal": "STF", "n": "449", "texto": "O valor da causa, na consignatória de aluguel, corresponde a uma anuidade.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3646; DJ de 09/10/1964, p. 3666; DJ de 12/10/1964, p. 3698.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula449/false"}, {"tribunal": "STF", "n": "450", "texto": "São devidos honorários de advogado sempre que vencedor o beneficiário de justiça gratuita.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3646; DJ de 09/10/1964, p. 3666; DJ de 12/10/1964, p. 3698.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula450/false"}, {"tribunal": "STF", "n": "451", "texto": "A competência especial por prerrogativa de função não se estende ao crime cometido após a cessação definitiva do exercício funcional.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3646; DJ de 09/10/1964, p. 3666; DJ de 12/10/1964, p. 3698.", "situacao": "Vigente", "obs": "Veja Súmula 394.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula451/false"}, {"tribunal": "STF", "n": "452", "texto": "Oficiais e praças do Corpo de Bombeiros do Estado da Guanabara respondem perante a Justiça Comum por crime anterior à L. 427, de 11.10.48.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3646; DJ de 09/10/1964, p. 3666; DJ de 12/10/1964, p. 3698.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula452/false"}, {"tribunal": "STF", "n": "453", "texto": "Não se aplicam à segunda instância o art. 384 e parágrafo único do Código de Processo Penal, que possibilitam dar nova definição jurídica ao fato delituoso, em virtude de circunstância elementar não contida, explícita ou implicitamente, na denúncia ou queixa.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3646; DJ de 09/10/1964, p. 3666; DJ de 12/10/1964, p. 3698.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula453/false"}, {"tribunal": "STF", "n": "454", "texto": "Simples interpretação de cláusulas contratuais não dá lugar a recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": "Veja Súmula 279.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula454/false"}, {"tribunal": "STF", "n": "455", "texto": "Da decisão que se seguir ao julgamento de constitucionalidade pelo Tribunal Pleno, são inadmissíveis embargos infringentes quanto à matéria constitucional.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": "Veja", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula455/false"}, {"tribunal": "STF", "n": "456", "texto": "O Supremo Tribunal Federal, conhecendo do recurso extraordinário, julgará a causa, aplicando o direito à espécie.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula456/false"}, {"tribunal": "STF", "n": "457", "texto": "O Tribunal Superior do Trabalho, conhecendo da revista, julgará a causa, aplicando o direito à espécie.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula457/false"}, {"tribunal": "STF", "n": "458", "texto": "O processo da execução trabalhista não exclui a remição pelo executado.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula458/false"}, {"tribunal": "STF", "n": "459", "texto": "No cálculo da indenização por despedida injusta, incluem-se os adicionais, ou gratificações, que, pela habitualidade, se tenham incorporado ao salário.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula459/false"}, {"tribunal": "STF", "n": "460", "texto": "Para efeito do adicional de insalubridade, a perícia judicial, em reclamação trabalhista, não dispensa o enquadramento da atividade entre as insalubres, que é ato da competência do Ministro do Trabalho e Previdência Social.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": "Veja Súmula 194.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula460/false"}, {"tribunal": "STF", "n": "461", "texto": "É duplo, e não triplo, o pagamento do salário nos dias destinados a descanso.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula461/false"}, {"tribunal": "STF", "n": "462", "texto": "No cálculo da indenização por despedida injusta inclui-se, quando devido, o repouso semanal remunerado.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": "Veja Súmula 207, Súmula 213, Súmula 214 e Súmula 313.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula462/false"}, {"tribunal": "STF", "n": "463", "texto": "Para efeito de indenização e estabilidade, conta-se o tempo em que o empregado esteve afastado, em serviço militar obrigatório, mesmo anteriormente à L. 4.072, de 1.6.62.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula463/false"}, {"tribunal": "STF", "n": "464", "texto": "No cálculo da indenização por acidente do trabalho inclui-se, quando devido, o repouso semanal remunerado.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula464/false"}, {"tribunal": "STF", "n": "465", "texto": "O regime de manutenção de salário, aplicável ao IAPM e ao IAPETC, exclui a indenização tarifada na Lei de Acidentes do Trabalho, mas não o benefício previdenciário.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula465/false"}, {"tribunal": "STF", "n": "466", "texto": "Não é inconstitucional a inclusão de sócios e administradores de sociedades e titulares de firmas individuais como contribuintes obrigatórios da previdência social.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula466/false"}, {"tribunal": "STF", "n": "467", "texto": "A base do cálculo das contribuições previdenciárias, anteriormente à vigência da Lei Orgânica da Previdência Social, é o salário mínimo mensal, observados os limites da L. 2.755 de 1956.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3647; DJ de 09/10/1964, p. 3667; DJ de 12/10/1964, p. 3699.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula467/false"}, {"tribunal": "STF", "n": "468", "texto": "Após a E. C. nº 5 de 21.11.61, em contrato firmado com a União, Estado, Município ou autarquia, é devido o impôsto federal de sêlo pelo contratante não protegido pela imunidade, ainda que haja repercussão do ônus tributário sôbre o patrimônio daquelas entidades.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3648; DJ de 09/10/1964, p. 3668; DJ de 12/10/1964, p. 3700.", "situacao": "Vigente", "obs": "Veja Súmula 303.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula468/false"}, {"tribunal": "STF", "n": "469", "texto": "A multa de cem por cento, para o caso de mercadoria importada irregularmente, é calculada à base do custo de câmbio da categoria correspondente.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3648; DJ de 09/10/1964, p. 3668; DJ de 12/10/1964, p. 3700.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula469/false"}, {"tribunal": "STF", "n": "470", "texto": "O impôsto de transmissão \"inter vivos\" não incide sôbre a construção, ou parte dela, realizada, inequivocamente, pelo promitente comprador, mas sôbre o valor do que tiver sido construído antes da promessa de venda.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3648; DJ de 09/10/1964, p. 3668; DJ de 12/10/1964, p. 3700.", "situacao": "Vigente", "obs": "Veja Súmula 110.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula470/false"}, {"tribunal": "STF", "n": "471", "texto": "As emprêsas aeroviárias não estão isentas do impôsto de indústrias e profissões.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3648; DJ de 09/10/1964, p. 3668; DJ de 12/10/1964, p. 3700.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula471/false"}, {"tribunal": "STF", "n": "472", "texto": "A condenação do autor em honorários de advogado, com fundamento no art. 64 do C. P. C., depende de reconvenção.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "01/10/1964", "pub": "DJ de 08/10/1964, p. 3648; DJ de 09/10/1964, p. 3668; DJ de 12/10/1964, p. 3700.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula472/false"}, {"tribunal": "STF", "n": "473", "texto": "A administração pode anular seus próprios atos, quando eivados de vícios que os tornam ilegais, porque dêles não se originam direitos; ou revogá-los, por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos, e ressalvada, em todos os casos, a apreciação judicial.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5929; DJ de 11/12/1969, p. 5945; DJ de 12/12/1969, p. 5993. Republicação: DJ de 11/06/1970, p. 2381; DJ de 12/06/1970, p. 2405; DJ de 15/06/1970, p. 2437.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula473/false"}, {"tribunal": "STF", "n": "474", "texto": "Não há direito líquido e certo, amparado pelo mandado de segurança, quando se escuda em lei cujos efeitos foram anulados por outra, declarada constitucional pelo Supremo Tribunal Federal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5929; DJ de 11/12/1969, p. 5945; DJ de 12/12/1969, p. 5993. Republicação: DJ de 11/06/1970, p. 2381; DJ de 12/06/1970, p. 2405; DJ de 15/06/1970, p. 2437.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula474/false"}, {"tribunal": "STF", "n": "475", "texto": "A Lei nº 4.686, de 21-6-65, tem aplicação imediata aos processos em curso, inclusive em grau de recurso extraordinário.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5929; DJ de 11/12/1969, p. 5945; DJ de 12/12/1969, p. 5993.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula475/false"}, {"tribunal": "STF", "n": "476", "texto": "Desapropriadas as ações de uma sociedade, o Poder desapropriante, imitido na posse, pode exercer, desde logo, todos os direitos inerentes aos respectivos títulos.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5929; DJ de 11/12/1969, p. 5945; DJ de 12/12/1969, p. 5993.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula476/false"}, {"tribunal": "STF", "n": "477", "texto": "As concessões de terras devolutas situadas na faixa de fronteira, feitas pelos Estados, autorizam, apenas, o uso, permanecendo o domínio com a União, ainda que se mantenha inerte ou tolerante, em relação aos possuidores.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5929; DJ de 11/12/1969, p. 5945; DJ de 12/12/1969, p. 5993. Republicação: DJ de 11/06/1970, p. 2381; DJ de 12/06/1970, p. 2405; DJ de 15/06/1970, p. 2437.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula477/false"}, {"tribunal": "STF", "n": "478", "texto": "O provimento em cargos de Juízes substitutos do Trabalho, deve ser feito independentemente de lista tríplice, na ordem de classificação dos candidatos.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5929; DJ de 11/12/1969, p. 5945; DJ de 12/12/1969, p. 5993.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula478/false"}, {"tribunal": "STF", "n": "479", "texto": "As margens dos rios navegáveis são de domínio público, insuscetíveis de expropriação e, por isso mesmo, excluídas de indenização.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5929; DJ de 11/12/1969, p. 5945; DJ de 12/12/1969, p. 5993.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula479/false"}, {"tribunal": "STF", "n": "480", "texto": "Pertencem ao domínio e administração da União, nos têrmos dos arts. 4º, IV e 186, da Constituição Federal de 1967, as terras ocupadas por silvícolas.", "vinculante": false, "materia": "", "ramo": "", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5930; DJ de 11/12/1969, p. 5946; DJ de 12/12/1969, p. 5994.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula480/false"}, {"tribunal": "STF", "n": "481", "texto": "Se a locação compreende, além do imóvel, fundo de comércio, com instalações e pertences, como no caso de teatros, cinemas e hotéis, não se aplicam ao retomante as restrições do art. 8º, \"e\", parágrafo único, do Decreto nº. 24.150, de 20.4.34.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5930; DJ de 11/12/1969, p. 5946; DJ de 12/12/1969, p. 5994.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula481/false"}, {"tribunal": "STF", "n": "482", "texto": "O locatário, que não fôr sucessor ou cessionário do que o precedeu na locação, não pode somar os prazos concedidos a este, para pedir a renovação do contrato, nos termos do Decreto nº 24.150.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5930; DJ de 11/12/1969, p. 5946; DJ de 12/12/1969, p. 5994.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula482/false"}, {"tribunal": "STF", "n": "483", "texto": "É dispensável a prova da necessidade, na retomada de prédio situado em localidade para onde o proprietário pretende transferir residência, salvo se mantiver, também, a anterior, quando dita prova será exigida.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5930; DJ de 11/12/1969, p. 5946; DJ de 12/12/1969, p. 5994.", "situacao": "Vigente", "obs": "Veja Súmula 80.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula483/false"}, {"tribunal": "STF", "n": "484", "texto": "Pode, legitimamente, o proprietário pedir o prédio para a residência de filho, ainda que solteiro, de acordo com o art. 11, nº III, da Lei nº 4.494, de 25.11.64.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5930; DJ de 11/12/1969, p. 5946; DJ de 12/12/1969, p. 5994.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula484/false"}, {"tribunal": "STF", "n": "485", "texto": "Nas locações regidas pelo Decreto nº 24.150, de 20 de abril de 1934, a presunção de sinceridade do retomante é relativa, podendo ser ilidida pelo locatário.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5930; DJ de 11/12/1969, p. 5946; DJ de 12/12/1969, p. 5994.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula485/false"}, {"tribunal": "STF", "n": "486", "texto": "Admite-se a retomada para sociedade da qual o locador, ou seu cônjuge, seja sócio, com participação predominante no capital social.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5930; DJ de 11/12/1969, p. 5946; DJ de 12/12/1969, p. 5994.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula486/false"}, {"tribunal": "STF", "n": "487", "texto": "Será deferida a posse a quem, evidentemente, tiver o domínio, se com base neste fôr ela disputada.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5930; DJ de 11/12/1969, p. 5946; DJ de 12/12/1969, p. 5994.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula487/false"}, {"tribunal": "STF", "n": "488", "texto": "A preferência a que se refere o art. 9º da Lei nº 3.912, de 3-7-1961, constitui direito pessoal. Sua violação resolve-se em perdas e danos.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula488/false"}, {"tribunal": "STF", "n": "489", "texto": "A compra e venda de automóvel não prevalece contra terceiros, de boa-fé, se o contrato não foi transcrito no Registro de Títulos e Documentos.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995. Republicação: DJ de 11/06/1970, p. 2381; DJ de 12/06/1970, p. 2405; DJ de 15/06/1970, p. 2437.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula489/false"}, {"tribunal": "STF", "n": "490", "texto": "A pensão correspondente à indenização oriunda de responsabilidade civil deve ser calculada com base no salário-mínimo vigente ao tempo da sentença e ajustar-se-á às variações ulteriores.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995. Republicação: DJ de 11/06/1970, p. 2381; DJ de 12/06/1970, p. 2405; DJ de 15/06/1970, p. 2437.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula490/false"}, {"tribunal": "STF", "n": "491", "texto": "É indenizável o acidente que cause a morte de filho menor, ainda que não exerça trabalho remunerado.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula491/false"}, {"tribunal": "STF", "n": "492", "texto": "A emprêsa locadora de veículos responde, civil e solidariamente com o locatário, pelos danos por este causados a terceiro, no uso do carro locado.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula492/false"}, {"tribunal": "STF", "n": "493", "texto": "O valor da indenização, se consistente em prestações periódicas e sucessivas, compreenderá, para que se mantenha inalterável na sua fixação, parcelas compensatórias do impôsto de renda, incidente sôbre os juros do capital gravado ou caucionado, nos termos dos arts. 911 e 912 do Código de Processo Civil.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula493/false"}, {"tribunal": "STF", "n": "494", "texto": "A ação para anular venda de ascendente a descendente, sem consentimento dos demais, prescreve em vinte anos, contados da data do ato, revogada a Súmula nº 152.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula494/false"}, {"tribunal": "STF", "n": "495", "texto": "A restituição em dinheiro da coisa vendida a crédito, entregue nos quinze dias anteriores ao pedido de falência ou de concordata, cabe, quando, ainda que consumida ou transformada, não faça o devedor prova de haver sido alienada a terceiro.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": "Veja Súmula 193 e Súmula 417.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula495/false"}, {"tribunal": "STF", "n": "496", "texto": "São válidos, porque salvaguardados pelas Disposições Constitucionais Transitórias da Constituição Federal de 1967, os decretos-leis expedidos entre 24 de janeiro e 15 de março de 1967.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula496/false"}, {"tribunal": "STF", "n": "497", "texto": "Quando se tratar de crime continuado, a prescrição regula-se pela pena imposta na sentença, não se computando o acréscimo decorrente da continuação.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula497/false"}, {"tribunal": "STF", "n": "498", "texto": "Compete à Justiça dos Estados, em ambas as instâncias, o processo e o julgamento dos crimes contra a economia popular.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula498/false"}, {"tribunal": "STF", "n": "499", "texto": "Não obsta à concessão do \"sursis\" condenação anterior à pena de multa.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula499/false"}, {"tribunal": "STF", "n": "500", "texto": "Não cabe a ação cominatória para compelir-se o réu a cumprir obrigação de dar.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995. Republicação: DJ de 11/06/1970, p. 2381; DJ de 12/06/1970, p. 2405; DJ de 15/06/1970, p. 2437.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula500/false"}, {"tribunal": "STF", "n": "501", "texto": "Compete à Justiça ordinária estadual o processo e o julgamento, em ambas as instâncias, das causas de acidente do trabalho, ainda que promovidas contra a União, suas autarquias, emprêsas públicas ou sociedades de economia mista.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5931; DJ de 11/12/1969, p. 5947; DJ de 12/12/1969, p. 5995. Republicação: DJ de 11/06/1970, p. 2381; DJ de 12/06/1970, p. 2405; DJ de 15/06/1970, p. 2437.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula501/false"}, {"tribunal": "STF", "n": "502", "texto": "Na aplicação do art. 839 do C. Pr. Civ., com a redação da Lei nº 4.290, de 5.12.63, a relação valor da causa e salário mínimo vigente na Capital do Estado, ou do Território, para o efeito de alçada, deve ser considerada na data do ajuizamento do pedido.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996. Republicação: DJ de 11/06/1970, p. 2382; DJ de 12/06/1970, p. 2406; DJ de 15/06/1970, p. 2438.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula502/false"}, {"tribunal": "STF", "n": "503", "texto": "A dúvida, suscitada por particular, sôbre o direito de tributar, manifestado por dois Estados, não configura litígio da competência originária do Supremo Tribunal Federal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula503/false"}, {"tribunal": "STF", "n": "504", "texto": "Compete à Justiça Federal, em ambas as instâncias, o processo e o julgamento das causas fundadas em contrato de seguro marítimo.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula504/false"}, {"tribunal": "STF", "n": "505", "texto": "Salvo quando contrariarem a Constituição, não cabe recurso para o Supremo Tribunal Federal, de quaisquer decisões da Justiça do Trabalho, inclusive dos presidentes de seus Tribunais.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula505/false"}, {"tribunal": "STF", "n": "506", "texto": "O agravo a que se refere o art. 4º da Lei nº 4.348, de 26.6.64, cabe, somente, do despacho do Presidente do Supremo Tribunal Federal que defere a suspensão da liminar, em mandado de segurança; não do que a denega.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": "Veja SS 1945 AgR-AgR-AgR-QO (DJ de 01/08/2003).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula506/false"}, {"tribunal": "STF", "n": "507", "texto": "A ampliação dos prazos a que se refere o art. 32 do Código de Processo Civil aplica-se aos executivos fiscais.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula507/false"}, {"tribunal": "STF", "n": "508", "texto": "Compete à Justiça Estadual, em ambas as instâncias, processar e julgar as causas em que fôr parte o Banco do Brasil S. A.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula508/false"}, {"tribunal": "STF", "n": "509", "texto": "A Lei nº 4.632, de 18.5.65, que alterou o art. 64 do Código de Processo Civil, aplica-se aos processos em andamento, nas instâncias ordinárias.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula509/false"}, {"tribunal": "STF", "n": "510", "texto": "Praticado o ato por autoridade, no exercício de competência delegada, contra ela cabe o mandado de segurança ou a medida judicial.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula510/false"}, {"tribunal": "STF", "n": "511", "texto": "Compete à Justiça Federal, em ambas as instâncias, processar e julgar as causas entre autarquias federais e entidades públicas locais, inclusive mandados de segurança, ressalvada a ação fiscal, nos termos da Constituição Federal de 1967, art. 119, § 3º.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula511/false"}, {"tribunal": "STF", "n": "512", "texto": "Não cabe condenação em honorários de advogado na ação de mandado de segurança.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula512/false"}, {"tribunal": "STF", "n": "513", "texto": "A decisão que enseja a interposição de recurso ordinário ou extraordinário não é a do plenário, que resolve o incidente de inconstitucionalidade, mas a do órgão (Câmaras, Grupos ou Turmas) que completa o julgamento do feito.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996. Republicação: DJ de 11/06/1970, p. 2382; DJ de 12/06/1970, p. 2406; DJ de 15/06/1970, p. 2438.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula513/false"}, {"tribunal": "STF", "n": "514", "texto": "Admite-se ação rescisória contra sentença transitada em julgado, ainda que contra ela não se tenha esgotado todos os recursos.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5932; DJ de 11/12/1969, p. 5948; DJ de 12/12/1969, p. 5996.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula514/false"}, {"tribunal": "STF", "n": "515", "texto": "A competência para a ação rescisória não é do Supremo Tribunal Federal, quando a questão federal, apreciada no recurso extraordinário ou no agravo de instrumento, seja diversa da que foi suscitada no pedido rescisório.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": "Veja Súmula 249.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula515/false"}, {"tribunal": "STF", "n": "516", "texto": "O Serviço Social da Indústria - S. E. S. I. - está sujeito à jurisdição da Justiça Estadual.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula516/false"}, {"tribunal": "STF", "n": "517", "texto": "As sociedades de economia mista só têm fôro na Justiça Federal, quando a União intervém como assistente ou opoente.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula517/false"}, {"tribunal": "STF", "n": "518", "texto": "A intervenção da União, em feito já julgado pela segunda instância e pendente de embargos, não desloca o processo para o Tribunal Federal de Recursos.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula518/false"}, {"tribunal": "STF", "n": "519", "texto": "Aplica-se aos executivos fiscais o princípio da sucumbência a que se refere o art. 64 do Código de Processo Civil.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula519/false"}, {"tribunal": "STF", "n": "520", "texto": "Não exige a lei que, para requerer o exame a que se refere o art. 777 do Código de Processo Penal, tenha o sentenciado cumprido mais de metade do prazo da medida de segurança imposta.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula520/false"}, {"tribunal": "STF", "n": "521", "texto": "O foro competente para o processo e julgamento dos crimes de estelionato, sob a modalidade da emissão dolosa de cheque sem provisão de fundos, é o do local onde se deu a recusa do pagamento pelo sacado.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula521/false"}, {"tribunal": "STF", "n": "522", "texto": "Salvo ocorrência de tráfico para o Exterior, quando, então, a competência será da Justiça Federal, compete à Justiça dos Estados o processo e julgamento dos crimes relativos a entorpecentes.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997. Republicação: DJ de 11/06/1970, p. 2382; DJ de 12/06/1970, p. 2406; DJ de 15/06/1970, p. 2438.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula522/false"}, {"tribunal": "STF", "n": "523", "texto": "No processo penal, a falta da defesa constitui nulidade absoluta, mas a sua deficiência só o anulará se houver prova de prejuízo para o réu.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula523/false"}, {"tribunal": "STF", "n": "524", "texto": "Arquivado o inquérito policial, por despacho do juiz, a requerimento do promotor de justiça, não pode a ação penal ser iniciada, sem novas provas.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula524/false"}, {"tribunal": "STF", "n": "525", "texto": "A medida de segurança não será aplicada em segunda instância, quando só o réu tenha recorrido.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997. Republicação: DJ de 11/06/1970, p. 2382; DJ de 12/06/1970, p. 2406; DJ de 15/06/1970, p. 2438.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula525/false"}, {"tribunal": "STF", "n": "526", "texto": "Subsiste a competência do Supremo Tribunal Federal para conhecer e julgar a apelação, nos crimes da Lei de Segurança Nacional, se houve sentença antes da vigência do A.I. nº 2.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997. Republicação: DJ de 11/06/1970, p. 2382; DJ de 12/06/1970, p. 2406; DJ de 15/06/1970, p. 2438.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula526/false"}, {"tribunal": "STF", "n": "527", "texto": "Após a vigência do Ato Institucional nº 6, que deu nova redação ao art. 114, III, da Constituição Federal de 1967, não cabe recurso extraordinário das decisões do juiz singular.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997. Republicação: DJ de 11/06/1970, p. 2382; DJ de 12/06/1970, p. 2406; DJ de 15/06/1970, p. 2438.", "situacao": "Vigente", "obs": "Veja Súmula 640.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula527/false"}, {"tribunal": "STF", "n": "528", "texto": "Se a decisão contiver partes autônomas, a admissão parcial, pelo Presidente do Tribunal a quo, de recurso extraordinário que, sôbre qualquer delas se manifestar, não limitará a apreciação de tôdas pelo Supremo Tribunal Federal, independentemente de interposição de agravo de instrumento.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5933; DJ de 11/12/1969, p. 5949; DJ de 12/12/1969, p. 5997.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula528/false"}, {"tribunal": "STF", "n": "529", "texto": "Subsiste a responsabilidade do empregador pela indenização decorrente de acidente do trabalho, quando o segurador, por haver entrado em liquidação, ou por outro motivo, não se encontrar em condições financeiras, de efetuar, na forma da lei, o pagamento que o seguro obrigatório visava garantir.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula529/false"}, {"tribunal": "STF", "n": "530", "texto": "Na legislação anterior ao art. 4º da Lei nº 4.749, de 12-8-1965, a contribuição para a previdência social não estava sujeita ao limite estabelecido no art. 69 da Lei nº 3.807, de 26 de agosto de 1960, sôbre o 13º salário a que se refere o art. 3º da Lei nº 4.281, de 8-11-63.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998. Republicação: DJ de 11/06/1970, p. 2382; DJ de 12/06/1970, p. 2406; DJ de 15/06/1970, p. 2438.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula530/false"}, {"tribunal": "STF", "n": "531", "texto": "É inconstitucional o Decreto nº 51.668, de 17-1-1963, que estabeleceu salário profissional para trabalhadores de transportes marítimos, fluviais e lacustres.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula531/false"}, {"tribunal": "STF", "n": "532", "texto": "É constitucional a Lei nº 5.043, de 21.6.66, que concedeu remissão das dívidas fiscais oriundas da falta de oportuno pagamento de sêlo nos contratos particulares com a Caixa Econômica e outras entidades autárquicas.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula532/false"}, {"tribunal": "STF", "n": "533", "texto": "Nas operações denominadas \"crediários\", com emissão de vales ou certificados para compras e nas quais, pelo financiamento, se cobram, em separado, juros, selos e outras despesas, incluir-se-á tudo no custo da mercadoria e sôbre esse preço global calcular-se-á o impôsto de vendas e consignações.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula533/false"}, {"tribunal": "STF", "n": "534", "texto": "O impôsto de importação sôbre o extrato alcoólico de malte, como matéria-prima para fabricação de whisky, incide à base de 60%, desde que desembarcado antes do Ddecreto-lei nº 398, de 30.12.1968.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula534/false"}, {"tribunal": "STF", "n": "535", "texto": "Na importação, a granel, de combustíveis líquidos é admíssivel a diferença de pêso, para mais, até 4%, motivada pelas variações previstas no Decreto-lei nº 1.028, de 4-1-1939, art. 1º.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula535/false"}, {"tribunal": "STF", "n": "536", "texto": "São objetivamente imunes ao impôsto sôbre circulação de mercadorias os produtos industrializados, em geral, destinados à exportação, além de outros, com a mesma destinação, cuja isenção a lei determinar.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula536/false"}, {"tribunal": "STF", "n": "537", "texto": "É inconstitucional a exigência de impôsto estadual do sêlo, quando feita nos atos e instrumentos tributados ou regulados por lei federal, ressalvado o disposto no art. 15, § 5º, da Constituição Federal de 1946.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula537/false"}, {"tribunal": "STF", "n": "538", "texto": "A avaliação judicial para o efeito do cálculo das benfeitorias dedutíveis do impôsto sôbre lucro imobiliário independe do limite a que se refere a Lei nº 3.470, de 28-11-1958, art. 8º, parágrafo único.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998. Republicação: DJ de 11/06/1970, p. 2383; DJ de 12/06/1970, p. 2407; DJ de 15/06/1970, p. 2439.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula538/false"}, {"tribunal": "STF", "n": "539", "texto": "É constitucional a lei do Município que reduz o impôsto predial urbano sôbre imóvel ocupado pela residência do proprietário, que não possua outro.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula539/false"}, {"tribunal": "STF", "n": "540", "texto": "No preço da mercadoria sujeita ao impôsto de vendas e consignações, não se incluem as despesas de frete e carreto.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5934; DJ de 11/12/1969, p. 5950; DJ de 12/12/1969, p. 5998.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula540/false"}, {"tribunal": "STF", "n": "541", "texto": "O impôsto sôbre vendas e consignações não incide sôbre a venda ocasional de veículos e equipamentos usados, que não se insere na atividade profissional do vendedor, e não é realizada com o fim de lucro, sem caráter, pois, de comercialidade.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 32.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula541/false"}, {"tribunal": "STF", "n": "542", "texto": "Não é inconstitucional a multa instituída pelo Estado-membro, como sanção pelo retardamento do início ou da ultimação do inventário.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula542/false"}, {"tribunal": "STF", "n": "543", "texto": "A Lei nº 2.975, de 27-11-1965, revogou, apenas, as isenções de caráter geral, relativas ao impôsto único sôbre combustíveis, não as especiais, por outras leis concedidas.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula543/false"}, {"tribunal": "STF", "n": "544", "texto": "Isenções tributárias concedidas, sob condição onerosa, não podem ser livremente suprimidas.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula544/false"}, {"tribunal": "STF", "n": "545", "texto": "Preços de serviços públicos e taxas não se confundem, porque estas, diferentemente daqueles, são compulsórias e têm sua cobrança condicionada à prévia autorização orçamentária, em relação à lei que as instituiu.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula545/false"}, {"tribunal": "STF", "n": "546", "texto": "Cabe a restituição do tributo pago indevidamente, quando reconhecido por decisão, que o contribuinte \"de jure\" não recuperou do contribuinte \"de facto o quantum\" respectivo.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": "Veja Súmula 71.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula546/false"}, {"tribunal": "STF", "n": "547", "texto": "Não é lícito à autoridade proibir que o contribuinte em débito adquira estampilhas, despache mercadorias nas alfândegas e exerça suas atividades profissionais.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999. Republicação: DJ de 11/06/1970, p. 2383; DJ de 12/06/1970, p. 2407; DJ de 15/06/1970, p. 2439.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula547/false"}, {"tribunal": "STF", "n": "548", "texto": "É inconstitucional o Decreto-lei nº 643, de 19.6.47, artigo 4º, do Paraná, na parte que exige sêlo proporcional sôbre atos e instrumentos regulados por lei federal.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula548/false"}, {"tribunal": "STF", "n": "549", "texto": "A Taxa de Bombeiros do Estado de Pernambuco é constitucional, revogada a Súmula nº 274.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula549/false"}, {"tribunal": "STF", "n": "550", "texto": "A isenção concedida pelo art. 2º da Lei nº 1.815 de 1953, às emprêsas de navegação aérea não compreende a taxa de melhoramento de portos, instituída pela Lei nº 3.421 de 1958.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula550/false"}, {"tribunal": "STF", "n": "551", "texto": "É inconstitucional a taxa de urbanização da Lei número 2.320, de 20-12-1961, instituída pelo Município de Pôrto Alegre, porque seu fato gerador é o mesmo da transmissão imobiliária.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "03/12/1969", "pub": "DJ de 10/12/1969, p. 5935; DJ de 11/12/1969, p. 5951; DJ de 12/12/1969, p. 5999.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula551/false"}, {"tribunal": "STF", "n": "552", "texto": "Com a regulamentação do art. 15 da Lei nº 5.316/67, pelo Decreto 71.037/72, tornou-se exeqüível a exigência da exaustão da via administrativa antes do início da ação de acidente do trabalho.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 1; DJ de 04/01/1977, p. 33; DJ de 05/01/1977, p. 57.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula552/false"}, {"tribunal": "STF", "n": "553", "texto": "O Adicional ao Frete para Renovação da Marinha Mercante (AFRMM) é contribuição parafiscal, não sendo abrangido pela imunidade prevista na letra d, inciso III, do art. 19, da Constituição Federal.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 1; DJ de 04/01/1977, p. 33; DJ de 05/01/1977, p. 57.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula553/false"}, {"tribunal": "STF", "n": "554", "texto": "O pagamento de cheque emitido sem provisão de fundos, após o recebimento da denúncia, não obsta ao prosseguimento da ação penal.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 1; DJ de 04/01/1977, p. 33; DJ de 05/01/1977, p. 57.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula554/false"}, {"tribunal": "STF", "n": "555", "texto": "É competente o Tribunal de Justiça para julgar conflito de jurisdição entre Juiz de Direito do Estado e a Justiça Militar local.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 1; DJ de 04/01/1977, p. 33; DJ de 05/01/1977, p. 57.", "situacao": "Vigente", "obs": "Veja CJ 6195 (DJ de 28/09/1979) e CJ 6155 (DJ de 25/05/1979).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula555/false"}, {"tribunal": "STF", "n": "556", "texto": "É competente a Justiça comum para julgar as causas em que é parte sociedade de economia mista.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 1; DJ de 04/01/1977, p. 33; DJ de 05/01/1977, p. 57.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula556/false"}, {"tribunal": "STF", "n": "557", "texto": "É competente a Justiça Federal para julgar as causas em que são partes a COBAL e a CIBRAZEM.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 2; DJ de 04/01/1977, p. 34; DJ de 05/01/1977, p. 58.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula557/false"}, {"tribunal": "STF", "n": "558", "texto": "É constitucional o art. 27 do Decreto-lei 898, de 29.9.69.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 2; DJ de 04/01/1977, p. 34; DJ de 05/01/1977, p. 58.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula558/false"}, {"tribunal": "STF", "n": "559", "texto": "O Decreto-lei 730, de 5.8.69, revogou a exigência de homologação, pelo Ministro da Fazenda, das Resoluções do Conselho de Política Aduaneira.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 2; DJ de 04/01/1977, p. 34; DJ de 05/01/1977, p. 58.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula559/false"}, {"tribunal": "STF", "n": "560", "texto": "A extinção de punibilidade, pelo pagamento do tributo devido, estende-se ao crime de contrabando ou descaminho, por força do art. 18, § 2º, do Decreto-lei 157/67.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 2; DJ de 04/01/1977, p. 34; DJ de 05/01/1977, p. 58.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula560/false"}, {"tribunal": "STF", "n": "561", "texto": "Em desapropriação, é devida a correção monetária até a data do efetivo pagamento da indenização, devendo proceder-se à atualização do cálculo, ainda que por mais de uma vez.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 2; DJ de 04/01/1977, p. 34; DJ de 05/01/1977, p. 58.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula561/false"}, {"tribunal": "STF", "n": "562", "texto": "Na indenização de danos materiais decorrentes de ato ilícito cabe a atualização de seu valor, utilizando-se, para esse fim, dentre outros critérios, dos índices de correção monetária.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 3; DJ de 04/01/1977, p. 35; DJ de 05/01/1977, p. 59.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula562/false"}, {"tribunal": "STF", "n": "563", "texto": "O concurso de preferência a que se refere o parágrafo único do art. 187 do Código Tributário Nacional é compatível com o disposto no art. 9º, inciso I, da Constituição Federal. (Cancelada)", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 3; DJ de 04/01/1977, p. 35; DJ de 05/01/1977, p. 59.", "situacao": "Cancelada", "obs": "A Súmula 563 foi cancelada no julgamento da ADPF 357 (DJe nº 104 de 07/10/2021).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula563/false"}, {"tribunal": "STF", "n": "564", "texto": "A ausência de fundamentação do despacho de recebimento de denúncia por crime falimentar enseja nulidade processual, salvo se já houver sentença condenatória.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 3; DJ de 04/01/1977, p. 35; DJ de 05/01/1977, p. 59.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula564/false"}, {"tribunal": "STF", "n": "565", "texto": "A multa fiscal moratória constitui pena administrativa, não se incluindo no crédito habilitado em falência.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 3; DJ de 04/01/1977, p. 35; DJ de 05/01/1977, p. 59.", "situacao": "Vigente", "obs": "Veja Súmula 191 e Súmula 192.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula565/false"}, {"tribunal": "STF", "n": "566", "texto": "Enquanto pendente, o pedido de readaptação fundado em desvio funcional não gera direitos para o servidor, relativamente ao cargo pleiteado.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 3; DJ de 04/01/1977, p. 35; DJ de 05/01/1977, p. 59.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula566/false"}, {"tribunal": "STF", "n": "567", "texto": "A constituição, ao assegurar, no § 3º do art. 102, a contagem integral do tempo de serviço público federal, estadual ou municipal para os efeitos de aposentadoria e disponibilidade não proíbe à União, aos Estados e aos Municípios mandarem contar, mediante lei, para efeito diverso, tempo de serviço prestado a outra pessoa de direito público interno.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 3; DJ de 04/01/1977, p. 35; DJ de 05/01/1977, p. 59.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula567/false"}, {"tribunal": "STF", "n": "568", "texto": "A identificação criminal não constitui constrangimento ilegal, ainda que o indiciado já tenha sido identificado civilmente.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 3; DJ de 04/01/1977, p. 35; DJ de 05/01/1977, p. 59.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula568/false"}, {"tribunal": "STF", "n": "569", "texto": "É inconstitucional a discriminação de alíquotas do imposto de circulação de mercadorias nas operações interestaduais, em razão de o destinatário ser, ou não, contribuinte.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 4; DJ de 04/01/1977, p. 36; DJ de 05/01/1977, p. 60.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula569/false"}, {"tribunal": "STF", "n": "570", "texto": "O impôsto de circulação de mercadorias não incide sobre a importação de bens de capital.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 4; DJ de 04/01/1977, p. 36; DJ de 05/01/1977, p. 60.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula570/false"}, {"tribunal": "STF", "n": "571", "texto": "O comprador de café ao IBC, ainda que sem expedição de nota fiscal, habilita-se, quando da comercialização do produto, ao crédito do ICM que incidiu sobre a operação anterior.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 4; DJ de 04/01/1977, p. 36; DJ de 05/01/1977, p. 60.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula571/false"}, {"tribunal": "STF", "n": "572", "texto": "No cálculo do imposto de circulação de mercadorias devido na saída de mercadorias para o exterior, não se incluem fretes pagos a terceiros, seguros e despesas de embarque.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 4; DJ de 04/01/1977, p. 36; DJ de 05/01/1977, p. 60.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula572/false"}, {"tribunal": "STF", "n": "573", "texto": "Não constitui fato gerador do imposto de circulação de mercadorias a saída física de máquinas, utensílios e implementos a título de comodato.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 4; DJ de 04/01/1977, p. 36; DJ de 05/01/1977, p. 60.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula573/false"}, {"tribunal": "STF", "n": "574", "texto": "Sem lei estadual que a estabeleça, é ilegítima a cobrança do imposto de circulação de mercadorias sobre o fornecimento de alimentação e bebidas em restaurante ou estabelecimento similar.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 4; DJ de 04/01/1977, p. 36; DJ de 05/01/1977, p. 60.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula574/false"}, {"tribunal": "STF", "n": "575", "texto": "À mercadoria importada de país signatário do GATT, ou membro da ALALC, estende-se a isenção do imposto de circulação de mercadorias concedida a similar nacional.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 4; DJ de 04/01/1977, p. 36; DJ de 05/01/1977, p. 60.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula575/false"}, {"tribunal": "STF", "n": "576", "texto": "É lícita a cobrança do imposto de circulação de mercadorias sobre produtos importados sob o regime da alíquota \"zero\".", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 5; DJ de 04/01/1977, p. 37; DJ de 05/01/1977, p. 61.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula576/false"}, {"tribunal": "STF", "n": "577", "texto": "Na importação de mercadorias do exterior, o fato gerador do imposto de circulação de mercadorias ocorre no momento de sua entrada no estabelecimento do importador.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 5; DJ de 04/01/1977, p. 37; DJ de 05/01/1977, p. 61.", "situacao": "Vigente", "obs": "Veja RE 193817 (DJ de 10/08/2001).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula577/false"}, {"tribunal": "STF", "n": "578", "texto": "Não podem os Estados, a título de ressarcimento de despesas, reduzir a parcela de 20% do produto da arrecadação do imposto de circulação de mercadorias, atribuída aos Municípios pelo art. 23, § 8º, da Constituição Federal.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 5; DJ de 04/01/1977, p. 37; DJ de 05/01/1977, p. 61.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula578/false"}, {"tribunal": "STF", "n": "579", "texto": "A cal virgem e a hidratada estão sujeitas ao imposto de circulação de mercadorias.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 5; DJ de 04/01/1977, p. 37; DJ de 05/01/1977, p. 61.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula579/false"}, {"tribunal": "STF", "n": "580", "texto": "A isenção prevista no art. 13, parágrafo único, do Decreto-lei 43/66, restringe-se aos filmes cinematográficos.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 5; DJ de 04/01/1977, p. 37; DJ de 05/01/1977, p. 61.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula580/false"}, {"tribunal": "STF", "n": "581", "texto": "A exigência de transporte em navio de bandeira brasileira, para efeito de isenção tributária, legitimou-se com o advento do Decreto-lei nº 666, de 2.7.69.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 5; DJ de 04/01/1977, p. 37; DJ de 05/01/1977, p. 61.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula581/false"}, {"tribunal": "STF", "n": "582", "texto": "É constitucional a Resolução nº 640/69, do Conselho de Política Aduaneira, que reduziu a alíquota do imposto de importação para a soda cáustica, destinada a zonas de difícil distribuição e abastecimento.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 5; DJ de 04/01/1977, p. 37; DJ de 05/01/1977, p. 61.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula582/false"}, {"tribunal": "STF", "n": "583", "texto": "Promitente-Comprador de imóvel residencial transcrito em nome de autarquia é contribuinte do imposto predial territorial urbano.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 6; DJ de 04/01/1977, p. 38; DJ de 05/01/1977, p. 62.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula583/false"}, {"tribunal": "STF", "n": "584", "texto": "Ao imposto de renda calculado sobre os rendimentos do ano-base, aplica-se a lei vigente no exercício financeiro em que deve ser apresentada a declaração. (Cancelada)", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 6; DJ de 04/01/1977, p. 38; DJ de 05/01/1977, p. 62.", "situacao": "Cancelada", "obs": "A Súmula 584 foi cancelada no julgamento do RE 159180 (DJe nº 204 de 17/08/2020).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula584/false"}, {"tribunal": "STF", "n": "585", "texto": "Não incide o imposto de renda sobre a remessa de divisas para pagamento de serviços prestados no exterior, por empresa que não opera no Brasil.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 6; DJ de 04/01/1977, p. 38; DJ de 05/01/1977, p. 62.", "situacao": "Vigente", "obs": "Veja RE 101066 (DJ de 19/10/1984).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula585/false"}, {"tribunal": "STF", "n": "586", "texto": "Incide imposto de renda sobre os juros remetidos para o exterior, com base em contrato de mútuo.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 6; DJ de 04/01/1977, p. 38; DJ de 05/01/1977, p. 62.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula586/false"}, {"tribunal": "STF", "n": "587", "texto": "Incide imposto de renda sobre o pagamento de serviços técnicos contratados no exterior e prestados no Brasil.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 6; DJ de 04/01/1977, p. 38; DJ de 05/01/1977, p. 62.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula587/false"}, {"tribunal": "STF", "n": "588", "texto": "O imposto sobre serviços não incide sobre os depósitos, as comissões e taxas de desconto, cobrados pelos estabelecimentos bancários.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 6; DJ de 04/01/1977, p. 38; DJ de 05/01/1977, p. 62.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula588/false"}, {"tribunal": "STF", "n": "589", "texto": "É inconstitucional a fixação de adicional progressivo do imposto predial e territorial urbano em função do número de imóveis do contribuinte.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 6; DJ de 04/01/1977, p. 38; DJ de 05/01/1977, p. 62.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula589/false"}, {"tribunal": "STF", "n": "590", "texto": "Calcula-se o imposto de transmissão causa mortis sobre o saldo credor da promessa de compra e venda de imóvel, no momento da abertura da sucessão do promitente vendedor.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 7; DJ de 04/01/1977, p. 39; DJ de 05/01/1977, p. 63.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula590/false"}, {"tribunal": "STF", "n": "591", "texto": "A imunidade ou a isenção tributária do comprador não se estende ao produtor, contribuinte do imposto sobre produtos industrializados.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 7; DJ de 04/01/1977, p. 39; DJ de 05/01/1977, p. 63.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula591/false"}, {"tribunal": "STF", "n": "592", "texto": "Nos crimes falimentares, aplicam-se as causas interruptivas da prescrição, previstas no Código Penal.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 7; DJ de 04/01/1977, p. 39; DJ de 05/01/1977, p. 63.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula592/false"}, {"tribunal": "STF", "n": "593", "texto": "Incide o percentual do Fundo de Garantia do Tempo de Serviço (FGTS) sobre a parcela da remuneração correspondente a horas extraordinárias de trabalho.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 7; DJ de 04/01/1977, p. 39; DJ de 05/01/1977, p. 63.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula593/false"}, {"tribunal": "STF", "n": "594", "texto": "Os direitos de queixa e de representação podem ser exercidos, independentemente, pelo ofendido ou por seu representante legal.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 7; DJ de 04/01/1977, p. 39; DJ de 05/01/1977, p. 63.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula594/false"}, {"tribunal": "STF", "n": "595", "texto": "É inconstitucional a taxa municipal de conservação de estradas de rodagem cuja base de cálculo seja idêntica à do imposto territorial rural.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 7; DJ de 04/01/1977, p. 39; DJ de 05/01/1977, p. 63.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula595/false"}, {"tribunal": "STF", "n": "596", "texto": "As disposições do Decreto 22.626/33 não se aplicam às taxas de juros e aos outros encargos cobrados nas operações realizadas por instituições públicas ou privadas, que integram o sistema financeiro nacional.", "vinculante": false, "materia": "Civil", "ramo": "Civil", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 7; DJ de 04/01/1977, p. 39; DJ de 05/01/1977, p. 63.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula596/false"}, {"tribunal": "STF", "n": "597", "texto": "Não cabem embargos infringentes de acórdão que, em mandado de segurança decidiu, por maioria de votos, a apelação.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 8; DJ de 04/01/1977, p. 40; DJ de 05/01/1977, p. 64.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula597/false"}, {"tribunal": "STF", "n": "598", "texto": "Nos embargos de divergência não servem como padrão de discordância os mesmos paradigmas invocados para demonstrá-la mas repelidos como não dissidentes no julgamento do recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 8; DJ de 04/01/1977, p. 40; DJ de 05/01/1977, p. 64.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula598/false"}, {"tribunal": "STF", "n": "599", "texto": "São incabíveis embargos de divergência de decisão de turma, em agravo regimental. (Cancelada)", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 8; DJ de 04/01/1977, p. 40; DJ de 05/01/1977, p. 64.", "situacao": "Cancelada", "obs": "A Súmula 599 foi cancelada nos seguintes julgamentos: RE 356069 AgR-EDv-AgR (DJe nº 55 de 28/03/2008), RE 285093 AgR-ED-EDv-AgR (DJe nº 55 28/03/2008) e RE 283240 AgR-ED-EDv-AgR (DJe nº 47 14/03/2008).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula599/false"}, {"tribunal": "STF", "n": "600", "texto": "Cabe ação executiva contra o emitente e seus avalistas, ainda que não apresentado o cheque ao sacado no prazo legal, desde que não prescrita a ação cambiária.", "vinculante": false, "materia": "Empresarial", "ramo": "Empresarial", "orgao": "Tribunal Pleno", "data": "15/12/1976", "pub": "DJ de 03/01/1977, p. 8; DJ de 04/01/1977, p. 40; DJ de 05/01/1977, p. 64.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula600/false"}, {"tribunal": "STF", "n": "601", "texto": "Os arts. 3º, II, e 55 da Lei Complementar nº 40/81 (Lei Orgânica do Ministério Público) não revogaram a legislação anterior que atribui a iniciativa para a ação penal pública, no processo sumário, ao juiz ou à autoridade policial, mediante Portaria ou Auto de Prisão em Flagrante.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18113; DJ de 30/10/1984, p. 18201; DJ de 31/10/1984, p. 18285.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula601/false"}, {"tribunal": "STF", "n": "602", "texto": "Nas causas criminais, o prazo de interposição de Recurso Extraordinário é de 10 (dez) dias.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18113; DJ de 30/10/1984, p. 18201; DJ de 31/10/1984, p. 18285.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula602/false"}, {"tribunal": "STF", "n": "603", "texto": "A competência para o processo e julgamento de latrocínio é do Juiz singular e não do Tribunal do Júri.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18113; DJ de 30/10/1984, p. 18201; DJ de 31/10/1984, p. 18285.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula603/false"}, {"tribunal": "STF", "n": "604", "texto": "A prescrição pela pena em concreto é somente da pretensão executória da pena privativa de liberdade.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18113; DJ de 30/10/1984, p. 18201; DJ de 31/10/1984, p. 18285.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula604/false"}, {"tribunal": "STF", "n": "605", "texto": "Não se admite continuidade delitiva nos crimes contra a vida.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18113; DJ de 30/10/1984, p. 18201; DJ de 31/10/1984, p. 18285.", "situacao": "Vigente", "obs": "Veja HC 77786 (DJ de 02/02/2001).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula605/false"}, {"tribunal": "STF", "n": "606", "texto": "Não cabe habeas corpus originário para o Tribunal Pleno de decisão de Turma, ou do Plenário, proferida em habeas corpus ou no respectivo recurso.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18113; DJ de 30/10/1984, p. 18201; DJ de 31/10/1984, p. 18285.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula606/false"}, {"tribunal": "STF", "n": "607", "texto": "Na ação penal regida pela Lei nº 4611/65, a denúncia, como substitutivo da Portaria, não interrompe a prescrição.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18113; DJ de 30/10/1984, p. 18201; DJ de 31/10/1984, p. 18285.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula607/false"}, {"tribunal": "STF", "n": "608", "texto": "No crime de estupro, praticado mediante violência real, a ação penal é pública incondicionada.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18113; DJ de 30/10/1984, p. 18201; DJ de 31/10/1984, p. 18285.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula608/false"}, {"tribunal": "STF", "n": "609", "texto": "É pública incondicionada a ação penal por crime de sonegação fiscal.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18114; DJ de 30/10/1984, p. 18202; DJ de 31/10/1984, p. 18286.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula609/false"}, {"tribunal": "STF", "n": "610", "texto": "Há crime de latrocínio, quando o homicídio se consuma, ainda que não realize o agente a subtração de bens da vítima.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18114; DJ de 30/10/1984, p. 18202; DJ de 31/10/1984, p. 18286.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula610/false"}, {"tribunal": "STF", "n": "611", "texto": "Transitada em julgado a sentença condenatória, compete ao Juízo das execuções a aplicação de lei mais benigna.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18114; DJ de 30/10/1984, p. 18202; DJ de 31/10/1984, p. 18286.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula611/false"}, {"tribunal": "STF", "n": "612", "texto": "Ao trabalhador rural não se aplicam, por analogia, os benefícios previstos na Lei nº 6367, de 19/10/76.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18114; DJ de 30/10/1984, p. 18202; DJ de 31/10/1984, p. 18286.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula612/false"}, {"tribunal": "STF", "n": "613", "texto": "Os dependentes de trabalhador rural não têm direito à pensão previdenciária, se o óbito ocorreu anteriormente à vigência da Lei Complementar nº 11/71.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18114; DJ de 30/10/1984, p. 18202; DJ de 31/10/1984, p. 18286.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula613/false"}, {"tribunal": "STF", "n": "614", "texto": "Somente o Procurador-Geral da Justiça tem legitimidade para propor ação direta interventiva por inconstitucionalidade de Lei Municipal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18115; DJ de 30/10/1984, p. 18203; DJ de 31/10/1984, p. 18287.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula614/false"}, {"tribunal": "STF", "n": "615", "texto": "O princípio constitucional da anualidade (§ 29 do art. 153 da CF) não se aplica à revogação de isenção do ICM.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18115; DJ de 30/10/1984, p. 18203; DJ de 31/10/1984, p. 18287.", "situacao": "Vigente", "obs": "Veja Súmula 544.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula615/false"}, {"tribunal": "STF", "n": "616", "texto": "É permitida a cumulação da multa contratual com os honorários de advogado, após o advento do Código de Processo Civil vigente.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18115; DJ de 30/10/1984, p. 18203; DJ de 31/10/1984, p. 18287.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula616/false"}, {"tribunal": "STF", "n": "617", "texto": "A base de cálculo dos honorários de advogado em desapropriação é a diferença entre a oferta e a indenização, corrigidas ambas monetariamente.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18115; DJ de 30/10/1984, p. 18203; DJ de 31/10/1984, p. 18287.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula617/false"}, {"tribunal": "STF", "n": "618", "texto": "Na desapropriação, direta ou indireta, a taxa dos juros compensatórios é de 12% (doze por cento) ao ano.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18115; DJ de 30/10/1984, p. 18203; DJ de 31/10/1984, p. 18287.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula618/false"}, {"tribunal": "STF", "n": "619", "texto": "A prisão do depositário judicial pode ser decretada no próprio processo em que se constituiu o encargo, independentemente da propositura de ação de depósito. (Revogada)", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18115; DJ de 30/10/1984, p. 18203; DJ de 31/10/1984, p. 18287.", "situacao": "Cancelada", "obs": "A Súmula 619 foi revogada no julgamento do HC 92566 (DJe nº 104 de 05/06/2009).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula619/false"}, {"tribunal": "STF", "n": "620", "texto": "A sentença proferida contra Autarquias não está sujeita a reexame necessário, salvo quando sucumbente em execução de dívida ativa.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18115; DJ de 30/10/1984, p. 18203; DJ de 31/10/1984, p. 18287.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula620/false"}, {"tribunal": "STF", "n": "621", "texto": "Não enseja embargos de terceiro à penhora a promessa de compra e venda não inscrita no registro de imóveis.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "17/10/1984", "pub": "DJ de 29/10/1984, p. 18115; DJ de 30/10/1984, p. 18203; DJ de 31/10/1984, p. 18287.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula621/false"}, {"tribunal": "STF", "n": "622", "texto": "Não cabe agravo regimental contra decisão do relator que concede ou indefere liminar em mandado de segurança.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula622/false"}, {"tribunal": "STF", "n": "623", "texto": "Não gera por si só a competência originária do Supremo Tribunal Federal para conhecer do mandado de segurança com base no art. 102, I, n, da Constituição, dirigir-se o pedido contra deliberação administrativa do tribunal de origem, da qual haja participado a maioria ou a totalidade de seus membros.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula623/false"}, {"tribunal": "STF", "n": "624", "texto": "Não compete ao Supremo Tribunal Federal conhecer originariamente de mandado de segurança contra atos de outros tribunais.", "vinculante": false, "materia": "", "ramo": "", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula624/false"}, {"tribunal": "STF", "n": "625", "texto": "Controvérsia sobre matéria de direito não impede concessão de mandado de segurança.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula625/false"}, {"tribunal": "STF", "n": "626", "texto": "A suspensão da liminar em mandado de segurança, salvo determinação em contrário da decisão que a deferir, vigorará até o trânsito em julgado da decisão definitiva de concessão da segurança ou, havendo recurso, até a sua manutenção pelo Supremo Tribunal Federal, desde que o objeto da liminar deferida coincida, total ou parcialmente, com o da impetração.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula626/false"}, {"tribunal": "STF", "n": "627", "texto": "No mandado de segurança contra a nomeação de magistrado da competência do Presidente da República, este é considerado autoridade coatora, ainda que o fundamento da impetração seja nulidade ocorrida em fase anterior do procedimento.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula627/false"}, {"tribunal": "STF", "n": "628", "texto": "Integrante de lista de candidatos a determinada vaga da composição de tribunal é parte legítima para impugnar a validade da nomeação de concorrente.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula628/false"}, {"tribunal": "STF", "n": "629", "texto": "A impetração de mandado de segurança coletivo por entidade de classe em favor dos associados independe da autorização destes.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula629/false"}, {"tribunal": "STF", "n": "630", "texto": "A entidade de classe tem legitimação para o mandado de segurança ainda quando a pretensão veiculada interesse apenas a uma parte da respectiva categoria.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula630/false"}, {"tribunal": "STF", "n": "631", "texto": "Extingue-se o processo de mandado de segurança se o impetrante não promove, no prazo assinado, a citação do litisconsorte passivo necessário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 1; DJ de 10/10/2003, p. 1; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula631/false"}, {"tribunal": "STF", "n": "632", "texto": "É constitucional lei que fixa o prazo de decadência para a impetração de mandado de segurança.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula632/false"}, {"tribunal": "STF", "n": "633", "texto": "É incabível a condenação em verba honorária nos recursos extraordinários interpostos em processo trabalhista, exceto nas hipóteses previstas na Lei 5.584/70.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula633/false"}, {"tribunal": "STF", "n": "634", "texto": "Não compete ao Supremo Tribunal Federal conceder medida cautelar para dar efeito suspensivo a recurso extraordinário que ainda não foi objeto de juízo de admissibilidade na origem.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula634/false"}, {"tribunal": "STF", "n": "635", "texto": "Cabe ao Presidente do Tribunal de origem decidir o pedido de medida cautelar em recurso extraordinário ainda pendente do seu juízo de admissibilidade.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula635/false"}, {"tribunal": "STF", "n": "636", "texto": "Não cabe recurso extraordinário por contrariedade ao princípio constitucional da legalidade, quando a sua verificação pressuponha rever a interpretação dada a normas infraconstitucionais pela decisão recorrida.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula636/false"}, {"tribunal": "STF", "n": "637", "texto": "Não cabe recurso extraordinário contra acórdão de Tribunal de Justiça que defere pedido de intervenção estadual em Município.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula637/false"}, {"tribunal": "STF", "n": "638", "texto": "A controvérsia sobre a incidência, ou não, de correção monetária em operações de crédito rural é de natureza infraconstitucional, não viabilizando recurso extraordinário.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula638/false"}, {"tribunal": "STF", "n": "639", "texto": "Aplica-se a Súmula 288 quando não constarem do traslado do agravo de instrumento as cópias das peças necessárias à verificação da tempestividade do recurso extraordinário não admitido pela decisão agravada.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": "Veja Súmula 288.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula639/false"}, {"tribunal": "STF", "n": "640", "texto": "É cabível recurso extraordinário contra decisão proferida por juiz de primeiro grau nas causas de alçada, ou por turma recursal de juizado especial cível e criminal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula640/false"}, {"tribunal": "STF", "n": "641", "texto": "Não se conta em dobro o prazo para recorrer, quando só um dos litisconsortes haja sucumbido.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula641/false"}, {"tribunal": "STF", "n": "642", "texto": "Não cabe ação direta de inconstitucionalidade de lei do Distrito Federal derivada da sua competência legislativa municipal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula642/false"}, {"tribunal": "STF", "n": "643", "texto": "O Ministério Público tem legitimidade para promover ação civil pública cujo fundamento seja a ilegalidade de reajuste de mensalidades escolares.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula643/false"}, {"tribunal": "STF", "n": "644", "texto": "Ao titular do cargo de procurador de autarquia não se exige a apresentação de instrumento de mandato para representá-la em juízo.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2. Republicação: DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 3; DJ de 11/12/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula644/false"}, {"tribunal": "STF", "n": "645", "texto": "É competente o Município para fixar o horário de funcionamento de estabelecimento comercial.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 38 e Súmula 419.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula645/false"}, {"tribunal": "STF", "n": "646", "texto": "Ofende o princípio da livre concorrência lei municipal que impede a instalação de estabelecimentos comerciais do mesmo ramo em determinada área.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 2; DJ de 10/10/2003, p. 2; DJ de 13/10/2003, p. 2.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 49.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula646/false"}, {"tribunal": "STF", "n": "647", "texto": "Compete privativamente à União legislar sobre vencimentos dos membros das polícias civil e militar do Distrito Federal.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 39.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula647/false"}, {"tribunal": "STF", "n": "648", "texto": "A norma do § 3º do art. 192 da Constituição, revogada pela EC 40/2003, que limitava a taxa de juros reais a 12% ao ano, tinha sua aplicabilidade condicionada à edição de lei complementar.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 7.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula648/false"}, {"tribunal": "STF", "n": "649", "texto": "É inconstitucional a criação, por Constituição estadual, de órgão de controle administrativo do Poder Judiciário do qual participem representantes de outros Poderes ou entidades.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula649/false"}, {"tribunal": "STF", "n": "650", "texto": "Os incisos I e XI do art. 20 da CF não alcançam terras de aldeamentos extintos, ainda que ocupadas por indígenas em passado remoto.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3. Republicação: DJ de 29/10/2003, p. 1; DJ de 30/10/2003, p. 1; DJ de 31/10/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula650/false"}, {"tribunal": "STF", "n": "651", "texto": "A medida provisória não apreciada pelo Congresso Nacional podia, até a EC 32/2001, ser reeditada dentro do seu prazo de eficácia de trinta dias, mantidos os efeitos de lei desde a primeira edição.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3. Republicação: DJ de 01/07/2004, p. 1; DJ de 02/07/2004, p. 1; DJ de 05/07/2004, p. 1.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 54.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula651/false"}, {"tribunal": "STF", "n": "652", "texto": "Não contraria a Constituição o art. 15, § 1º, do Dl. 3.365/41 (Lei da Desapropriação por utilidade pública).", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula652/false"}, {"tribunal": "STF", "n": "653", "texto": "No Tribunal de Contas estadual, composto por sete conselheiros, quatro devem ser escolhidos pela Assembléia Legislativa e três pelo Chefe do Poder Executivo estadual, cabendo a este indicar um dentre auditores e outro dentre membros do Ministério Público, e um terceiro a sua livre escolha.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula653/false"}, {"tribunal": "STF", "n": "654", "texto": "A garantia da irretroatividade da lei, prevista no art 5º, XXXVI, da Constituição da República, não é invocável pela entidade estatal que a tenha editado.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula654/false"}, {"tribunal": "STF", "n": "655", "texto": "A exceção prevista no art. 100, caput, da Constituição, em favor dos créditos de natureza alimentícia, não dispensa a expedição de precatório, limitando-se a isentá-los da observância da ordem cronológica dos precatórios decorrentes de condenações de outra natureza.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula655/false"}, {"tribunal": "STF", "n": "656", "texto": "É inconstitucional a lei que estabelece alíquotas progressivas para o imposto de transmissão inter vivos de bens imóveis - ITBI com base no valor venal do imóvel.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula656/false"}, {"tribunal": "STF", "n": "657", "texto": "A imunidade prevista no art. 150, VI, d, da Constituição Federal abrange os filmes e papéis fotográficos necessários à publicação de jornais e periódicos.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula657/false"}, {"tribunal": "STF", "n": "658", "texto": "São constitucionais os arts. 7º da Lei 7.787/89 e 1º da Lei 7.894/89 e da Lei 8.147/90, que majoraram a alíquota do Finsocial, quando devida a contribuição por empresas dedicadas exclusivamente à prestação de serviços.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula658/false"}, {"tribunal": "STF", "n": "659", "texto": "É legítima a cobrança da COFINS, do PIS e do FINSOCIAL sobre as operações relativas a energia elétrica, serviços de telecomunicações, derivados de petróleo, combustíveis e minerais do País.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula659/false"}, {"tribunal": "STF", "n": "660", "texto": "Não incide ICMS na importação de bens por pessoa física ou jurídica que não seja contribuinte do imposto.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3. Republicação: DJ de 05/08/2004, p. 1; DJ de 06/08/2004, p. 1; DJ de 09/08/2004, p. 1. Republicação: DJ de 28/03/2006, p. 1; DJ de 29/03/2006, p. 1; DJ de 30/03/2006, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula660/false"}, {"tribunal": "STF", "n": "661", "texto": "Na entrada de mercadoria importada do exterior, é legítima a cobrança do ICMS por ocasião do desembaraço aduaneiro.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": "Veja Sumula Vinculante 48", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula661/false"}, {"tribunal": "STF", "n": "662", "texto": "É legítima a incidência do ICMS na comercialização de exemplares de obras cinematográficas, gravados em fitas de videocassete.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula662/false"}, {"tribunal": "STF", "n": "663", "texto": "Os §§ 1º e 3º do art. 9º do Dl. 406/68 foram recebidos pela Constituição.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula663/false"}, {"tribunal": "STF", "n": "664", "texto": "É inconstitucional o inciso V do art. 1º da Lei 8.033/90, que instituiu a incidência do imposto nas operações de crédito, câmbio e seguros - IOF sobre saques efetuados em caderneta de poupança.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 3; DJ de 10/10/2003, p. 3; DJ de 13/10/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula664/false"}, {"tribunal": "STF", "n": "665", "texto": "É constitucional a Taxa de Fiscalização dos Mercados de Títulos e Valores Mobiliários instituída pela Lei 7.940/89.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula665/false"}, {"tribunal": "STF", "n": "666", "texto": "A contribuição confederativa de que trata o art. 8º, IV, da Constituição, só é exigível dos filiados ao sindicato respectivo.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 40.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula666/false"}, {"tribunal": "STF", "n": "667", "texto": "Viola a garantia constitucional de acesso à jurisdição a taxa judiciária calculada sem limite sobre o valor da causa.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula667/false"}, {"tribunal": "STF", "n": "668", "texto": "É inconstitucional a lei municipal que tenha estabelecido, antes da Emenda Constitucional 29/2000, alíquotas progressivas para o IPTU, salvo se destinada a assegurar o cumprimento da função social da propriedade urbana.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula668/false"}, {"tribunal": "STF", "n": "669", "texto": "Norma legal que altera o prazo de recolhimento da obrigação tributária não se sujeita ao princípio da anterioridade.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 50.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula669/false"}, {"tribunal": "STF", "n": "670", "texto": "O serviço de iluminação pública não pode ser remunerado mediante taxa.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 41.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula670/false"}, {"tribunal": "STF", "n": "671", "texto": "Os servidores públicos e os trabalhadores em geral têm direito, no que concerne à URP de abril/maio de 1988, apenas ao valor correspondente a 7/30 de 16,19% sobre os vencimentos e salários pertinentes aos meses de abril e maio de 1988, não cumulativamente, devidamente corrigido até o efetivo pagamento.", "vinculante": false, "materia": "", "ramo": "", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula671/false"}, {"tribunal": "STF", "n": "672", "texto": "O reajuste de 28,86%, concedido aos servidores militares pelas Leis 8.622/93 e 8.627/93, estende-se aos servidores civis do Poder Executivo, observadas as eventuais compensações decorrentes dos reajustes diferenciados concedidos pelos mesmos diplomas legais.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4. Republicação: DJ de 01/06/2004, p. 1; DJ de 02/06/2004, p. 1; DJ de 03/06/2004, p. 1.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 51.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula672/false"}, {"tribunal": "STF", "n": "673", "texto": "O art. 125, § 4º, da Constituição não impede a perda da graduação de militar mediante procedimento administrativo.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula673/false"}, {"tribunal": "STF", "n": "674", "texto": "A anistia prevista no art. 8º do ADCT não alcança os militares expulsos com base em legislação disciplinar ordinária, ainda que em razão de atos praticados por motivação política.", "vinculante": false, "materia": "Militar", "ramo": "Militar", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula674/false"}, {"tribunal": "STF", "n": "675", "texto": "Os intervalos fixados para descanso e alimentação durante a jornada de seis horas não descaracterizam o sistema de turnos ininterruptos de revezamento para o efeito do art. 7º, XIV, da Constituição.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula675/false"}, {"tribunal": "STF", "n": "676", "texto": "A garantia da estabilidade provisória prevista no art. 10, II, a, do ADCT, também se aplica ao suplente do cargo de direção de comissões internas de prevenção de acidentes (CIPA).", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula676/false"}, {"tribunal": "STF", "n": "677", "texto": "Até que lei venha a dispor a respeito, incumbe ao Ministério do Trabalho proceder ao registro das entidades sindicais e zelar pela observância do princípio da unicidade.", "vinculante": false, "materia": "Trabalhista", "ramo": "Trabalhista", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula677/false"}, {"tribunal": "STF", "n": "678", "texto": "São inconstitucionais os incisos I e III do art. 7º da Lei 8.162/91, que afastam, para efeito de anuênio e de licença-prêmio, a contagem do tempo de serviço regido pela CLT dos servidores que passaram a submeter-se ao Regime Jurídico Único.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula678/false"}, {"tribunal": "STF", "n": "679", "texto": "A fixação de vencimentos dos servidores públicos não pode ser objeto de convenção coletiva.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula679/false"}, {"tribunal": "STF", "n": "680", "texto": "O direito ao auxílio-alimentação não se estende aos servidores inativos.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 55.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula680/false"}, {"tribunal": "STF", "n": "681", "texto": "É inconstitucional a vinculação do reajuste de vencimentos de servidores estaduais ou municipais a índices federais de correção monetária.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 4; DJ de 10/10/2003, p. 4; DJ de 13/10/2003, p. 4.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 42.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula681/false"}, {"tribunal": "STF", "n": "682", "texto": "Não ofende a Constituição a correção monetária no pagamento com atraso dos vencimentos de servidores públicos.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula682/false"}, {"tribunal": "STF", "n": "683", "texto": "O limite de idade para a inscrição em concurso público só se legitima em face do art. 7º, XXX, da Constituição, quando possa ser justificado pela natureza das atribuições do cargo a ser preenchido.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": "Veja Súmula 14.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula683/false"}, {"tribunal": "STF", "n": "684", "texto": "É inconstitucional o veto não motivado à participação de candidato a concurso público.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula684/false"}, {"tribunal": "STF", "n": "685", "texto": "É inconstitucional toda modalidade de provimento que propicie ao servidor investir-se, sem prévia aprovação em concurso público destinado ao seu provimento, em cargo que não integra a carreira na qual anteriormente investido.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 43.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula685/false"}, {"tribunal": "STF", "n": "686", "texto": "Só por lei se pode sujeitar a exame psicotécnico a habilitação de candidato a cargo público.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 44.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula686/false"}, {"tribunal": "STF", "n": "687", "texto": "A revisão de que trata o art. 58 do ADCT não se aplica aos benefícios previdenciários concedidos após a promulgação da Constituição de 1988.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula687/false"}, {"tribunal": "STF", "n": "688", "texto": "É legítima a incidência da contribuição previdenciária sobre o 13º salário.", "vinculante": false, "materia": "Previdenciário", "ramo": "Previdenciário", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula688/false"}, {"tribunal": "STF", "n": "689", "texto": "O segurado pode ajuizar ação contra a instituição previdenciária perante o juízo federal do seu domicílio ou nas varas federais da Capital do Estado-Membro.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula689/false"}, {"tribunal": "STF", "n": "690", "texto": "Compete originariamente ao Supremo Tribunal Federal o julgamento de \"habeas corpus\" contra decisão de turma recursal de juizados especiais criminais.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": "- Veja HC 86834 (DJ de 09/03/2007). - Embora na publicação da Súmula 690 conste como precedente o HC 79570, trata-se do HC 79570 QO (DJ de 01/08/2003).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula690/false"}, {"tribunal": "STF", "n": "691", "texto": "Não compete ao Supremo Tribunal Federal conhecer de \"habeas corpus\" impetrado contra decisão do Relator que, em habeas corpus requerido a tribunal superior, indefere a liminar.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": "Veja HC 85185 (DJ de 01/09/2006) e HC 86864 MC (DJ de 16/12/2005).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula691/false"}, {"tribunal": "STF", "n": "692", "texto": "Não se conhece de \"habeas corpus\" contra omissão de relator de extradição, se fundado em fato ou direito estrangeiro cuja prova não constava dos autos, nem foi ele provocado a respeito.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula692/false"}, {"tribunal": "STF", "n": "693", "texto": "Não cabe \"habeas corpus\" contra decisão condenatória a pena de multa, ou relativo a processo em curso por infração penal a que a pena pecuniária seja a única cominada.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula693/false"}, {"tribunal": "STF", "n": "694", "texto": "Não cabe \"habeas corpus\" contra a imposição da pena de exclusão de militar ou de perda de patente ou de função pública.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula694/false"}, {"tribunal": "STF", "n": "695", "texto": "Não cabe \"habeas corpus\" quando já extinta a pena privativa de liberdade.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula695/false"}, {"tribunal": "STF", "n": "696", "texto": "Reunidos os pressupostos legais permissivos da suspensão condicional do processo, mas se recusando o Promotor de Justiça a propô-la, o Juiz, dissentindo, remeterá a questão ao Procurador-Geral, aplicando-se por analogia o art. 28 do Código de Processo Penal.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 5; DJ de 10/10/2003, p. 5; DJ de 13/10/2003, p. 5.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula696/false"}, {"tribunal": "STF", "n": "697", "texto": "A proibição de liberdade provisória nos processos por crimes hediondos não veda o relaxamento da prisão processual por excesso de prazo.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula697/false"}, {"tribunal": "STF", "n": "698", "texto": "Não se estende aos demais crimes hediondos a admissibilidade de progressão no regime de execução da pena aplicada ao crime de tortura.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": "Veja HC 82959 (DJ de 01/09/2006).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula698/false"}, {"tribunal": "STF", "n": "699", "texto": "O prazo para interposição de agravo, em processo penal, é de cinco dias, de acordo com a Lei 8.038/90, não se aplicando o disposto a respeito nas alterações da Lei 8.950/94 ao Código de Processo Civil.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula699/false"}, {"tribunal": "STF", "n": "700", "texto": "É de cinco dias o prazo para interposição de agravo contra decisão do juiz da execução penal.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula700/false"}, {"tribunal": "STF", "n": "701", "texto": "No mandado de segurança impetrado pelo Ministério Público contra decisão proferida em processo penal, é obrigatória a citação do réu como litisconsorte passivo.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula701/false"}, {"tribunal": "STF", "n": "702", "texto": "A competência do Tribunal de Justiça para julgar prefeitos restringe-se aos crimes de competência da Justiça comum estadual; nos demais casos, a competência originária caberá ao respectivo tribunal de segundo grau.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula702/false"}, {"tribunal": "STF", "n": "703", "texto": "A extinção do mandato do prefeito não impede a instauração de processo pela prática dos crimes previstos no art. 1º do Dl. 201/67.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula703/false"}, {"tribunal": "STF", "n": "704", "texto": "Não viola as garantias do juiz natural, da ampla defesa e do devido processo legal a atração por continência ou conexão do processo do co-réu ao foro por prerrogativa de função de um dos denunciados.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula704/false"}, {"tribunal": "STF", "n": "705", "texto": "A renúncia do réu ao direito de apelação, manifestada sem a assistência do defensor, não impede o conhecimento da apelação por este interposta.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula705/false"}, {"tribunal": "STF", "n": "706", "texto": "É relativa a nulidade decorrente da inobservância da competência penal por prevenção.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula706/false"}, {"tribunal": "STF", "n": "707", "texto": "Constitui nulidade a falta de intimação do denunciado para oferecer contra-razões ao recurso interposto da rejeição da denúncia, não a suprindo a nomeação de defensor dativo.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula707/false"}, {"tribunal": "STF", "n": "708", "texto": "É nulo o julgamento da apelação se, após a manifestação nos autos da renúncia do único defensor, o réu não foi previamente intimado para constituir outro.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula708/false"}, {"tribunal": "STF", "n": "709", "texto": "Salvo quando nula a decisão de primeiro grau, o acórdão que provê o recurso contra a rejeição da denúncia vale, desde logo, pelo recebimento dela.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula709/false"}, {"tribunal": "STF", "n": "710", "texto": "No processo penal, contam-se os prazos da data da intimação, e não da juntada aos autos do mandado ou da carta precatória ou de ordem.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula710/false"}, {"tribunal": "STF", "n": "711", "texto": "A lei penal mais grave aplica-se ao crime continuado ou ao crime permanente, se a sua vigência é anterior à cessação da continuidade ou da permanência.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula711/false"}, {"tribunal": "STF", "n": "712", "texto": "É nula a decisão que determina o desaforamento de processo da competência do júri sem audiência da defesa.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula712/false"}, {"tribunal": "STF", "n": "713", "texto": "O efeito devolutivo da apelação contra decisões do Júri é adstrito aos fundamentos da sua interposição.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula713/false"}, {"tribunal": "STF", "n": "714", "texto": "É concorrente a legitimidade do ofendido, mediante queixa, e do Ministério Público, condicionada à representação do ofendido, para a ação penal por crime contra a honra de servidor público em razão do exercício de suas funções.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula714/false"}, {"tribunal": "STF", "n": "715", "texto": "A pena unificada para atender ao limite de trinta anos de cumprimento, determinado pelo art. 75 do Código Penal, não é considerada para a concessão de outros benefícios, como o livramento condicional ou regime mais favorável de execução.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 6; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula715/false"}, {"tribunal": "STF", "n": "716", "texto": "Admite-se a progressão de regime de cumprimento da pena ou a aplicação imediata de regime menos severo nela determinada, antes do trânsito em julgado da sentença condenatória.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 6; DJ de 10/10/2003, p. 7; DJ de 13/10/2003, p. 6.", "situacao": "Vigente", "obs": "Veja HC 84078 (DJe nº 35 de 26/02/2010).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula716/false"}, {"tribunal": "STF", "n": "717", "texto": "Não impede a progressão de regime de execução da pena, fixada em sentença não transitada em julgado, o fato de o réu se encontrar em prisão especial.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 7; DJ de 10/10/2003, p. 7; DJ de 13/10/2003, p. 7.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula717/false"}, {"tribunal": "STF", "n": "718", "texto": "A opinião do julgador sobre a gravidade em abstrato do crime não constitui motivação idônea para a imposição de regime mais severo do que o permitido segundo a pena aplicada.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 7; DJ de 10/10/2003, p. 7; DJ de 13/10/2003, p. 7.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula718/false"}, {"tribunal": "STF", "n": "719", "texto": "A imposição do regime de cumprimento mais severo do que a pena aplicada permitir exige motivação idônea.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 7; DJ de 10/10/2003, p. 7; DJ de 13/10/2003, p. 7.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula719/false"}, {"tribunal": "STF", "n": "720", "texto": "O art. 309 do Código de Trânsito Brasileiro, que reclama decorra do fato perigo de dano, derrogou o art. 32 da Lei das Contravenções Penais no tocante à direção sem habilitação em vias terrestres.", "vinculante": false, "materia": "Penal", "ramo": "Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 7; DJ de 10/10/2003, p. 7; DJ de 13/10/2003, p. 7.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula720/false"}, {"tribunal": "STF", "n": "721", "texto": "A competência constitucional do Tribunal do Júri prevalece sobre o foro por prerrogativa de função estabelecido exclusivamente pela Constituição estadual.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "24/09/2003", "pub": "DJ de 09/10/2003, p. 7; DJ de 10/10/2003, p. 7; DJ de 13/10/2003, p. 7.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 45.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula721/false"}, {"tribunal": "STF", "n": "722", "texto": "São da competência legislativa da União a definição dos crimes de responsabilidade e o estabelecimento das respectivas normas de processo e julgamento.", "vinculante": false, "materia": "", "ramo": "", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 1; DJ de 10/12/2003, p. 1; DJ de 11/12/2003, p. 1.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 46.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula722/false"}, {"tribunal": "STF", "n": "723", "texto": "Não se admite a suspensão condicional do processo por crime continuado, se a soma da pena mínima da infração mais grave com o aumento mínimo de um sexto for superior a um ano.", "vinculante": false, "materia": "Processual Penal", "ramo": "Processual Penal", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 1; DJ de 10/12/2003, p. 1; DJ de 11/12/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula723/false"}, {"tribunal": "STF", "n": "724", "texto": "Ainda quando alugado a terceiros, permanece imune ao IPTU o imóvel pertencente a qualquer das entidades referidas pelo art. 150, VI, c, da Constituição, desde que o valor dos aluguéis seja aplicado nas atividades essenciais de tais entidades.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 1; DJ de 10/12/2003, p. 1; DJ de 11/12/2003, p. 1.", "situacao": "Vigente", "obs": "Veja Súmula Vinculante 52.", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula724/false"}, {"tribunal": "STF", "n": "725", "texto": "É constitucional o § 2º do art. 6º da L. 8.024/90, resultante da conversão da MPr 168/90, que fixou o BTN fiscal como índice de correção monetária aplicável aos depósitos bloqueados pelo Plano Collor I.", "vinculante": false, "materia": "Constitucional", "ramo": "Constitucional", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 1; DJ de 10/12/2003, p. 1; DJ de 11/12/2003, p. 1.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula725/false"}, {"tribunal": "STF", "n": "726", "texto": "Para efeito de aposentadoria especial de professores, não se computa o tempo de serviço prestado fora da sala de aula.", "vinculante": false, "materia": "Administrativo", "ramo": "Administrativo", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 1; DJ de 10/12/2003, p. 1; DJ de 11/12/2003, p. 1.", "situacao": "Vigente", "obs": "Veja ADI 3772 (DJe nº 59 de 27/03/2009).", "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula726/false"}, {"tribunal": "STF", "n": "727", "texto": "Não pode o magistrado deixar de encaminhar ao Supremo Tribunal Federal o agravo de instrumento interposto da decisão que não admite recurso extraordinário, ainda que referente a causa instaurada no âmbito dos juizados especiais.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 1; DJ de 10/12/2003, p. 2; DJ de 11/12/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula727/false"}, {"tribunal": "STF", "n": "728", "texto": "É de três dias o prazo para a interposição de recurso extraordinário contra decisão do Tribunal Superior Eleitoral, contado, quando for o caso, a partir da publicação do acórdão, na própria sessão de julgamento, nos termos do art. 12 da Lei 6.055/74, que não foi revogado pela Lei 8.950/94.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 2; DJ de 11/12/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula728/false"}, {"tribunal": "STF", "n": "729", "texto": "A decisão na ADC-4 não se aplica à antecipação de tutela em causa de natureza previdenciária.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 2; DJ de 11/12/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula729/false"}, {"tribunal": "STF", "n": "730", "texto": "A imunidade tributária conferida a instituições de assistência social sem fins lucrativos pelo art. 150, VI, c, da Constituição, somente alcança as entidades fechadas de previdência social privada se não houver contribuição dos beneficiários.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 2; DJ de 11/12/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula730/false"}, {"tribunal": "STF", "n": "731", "texto": "Para fim da competência originária do Supremo Tribunal Federal, é de interesse geral da magistratura a questão de saber se, em face da LOMAN, os juízes têm direito à licença-prêmio.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 2; DJ de 11/12/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula731/false"}, {"tribunal": "STF", "n": "732", "texto": "É constitucional a cobrança da contribuição do salário-educação, seja sob a Carta de 1969, seja sob a Constituição Federal de 1988, e no regime da Lei 9.424/96.", "vinculante": false, "materia": "Tributário", "ramo": "Tributário", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 2; DJ de 11/12/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula732/false"}, {"tribunal": "STF", "n": "733", "texto": "Não cabe recurso extraordinário contra decisão proferida no processamento de precatórios.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 2; DJ de 11/12/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula733/false"}, {"tribunal": "STF", "n": "734", "texto": "Não cabe reclamação quando já houver transitado em julgado o ato judicial que se alega tenha desrespeitado decisão do Supremo Tribunal Federal.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 2; DJ de 11/12/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula734/false"}, {"tribunal": "STF", "n": "735", "texto": "Não cabe recurso extraordinário contra acórdão que defere medida liminar.", "vinculante": false, "materia": "Processual Civil", "ramo": "Processual Civil", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 2; DJ de 11/12/2003, p. 2.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula735/false"}, {"tribunal": "STF", "n": "736", "texto": "Compete à Justiça do Trabalho julgar as ações que tenham como causa de pedir o descumprimento de normas trabalhistas relativas à segurança, higiene e saúde dos trabalhadores.", "vinculante": false, "materia": "Processual do Trabalho", "ramo": "Processual do Trabalho", "orgao": "Tribunal Pleno", "data": "26/11/2003", "pub": "DJ de 09/12/2003, p. 2; DJ de 10/12/2003, p. 3; DJ de 11/12/2003, p. 3.", "situacao": "Vigente", "obs": null, "url": "https://jurisprudencia.stf.jus.br/pages/search/seq-sumula736/false"}]);
